/* Evolvlings: English text for the era 7 path conversations (parallel to events-era7.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: the windmills, the Choir, Brisa, Arpegia, the Ford's song, the sold verse and the end ==================== */

  add("heights", {
    "e7-molinos": { who: { aspa: "Aspa, the Choir's miller" }, nodes: {
      a: { say: ["On the summit of the Heights twelve wooden windmills turn, tall as trees. Their sails grind no wheat: they catch the wind that rises from the depths of the Glade, a warm wind that smells of wet earth.",
                 "Aspa, the Choir's miller. I built them, with my brothers. The wind goes in through the sails, the Choir sings into it, and the song comes out the other side toward the whole Glade. And it sticks. Everyone sings it.",
                 "For the first time in a hundred years, the Heights have money. We don't go down to beg. They come up to buy. Do you know what that means to a summit that always drummed “we're short”?"],
           opts: ["“What's in that wind?”", "Break the windmills", "“Let them belong to the whole summit, not just the Choir.”", "Give them a song of your own", "Leave them as they are"] },
      viento: { say: ["Dreams. That's what the Deep folk say. That it rises from the Root, full of what the Root dreams. I don't know. I know a song sung on it isn't forgotten.",
                      "They say Brisa discovered it, the Choir's voice, when she was a girl, singing some nonsense about a goat in a hat. There are old folk who still hum it without meaning to."] },
      romper: { say: ["That night you climb the biggest windmill with an axe. You cut the sail ropes. The windmill spins wildly for a while, creaks, and stops.",
                      "Aspa comes running, in her nightgown. She looks at the broken windmill. She doesn't shout. She sits down in the snow.",
                      "One. Eleven left. Tomorrow I'll fix it. But now I know someone can climb up with an axe. That can't be fixed."] },
      cumbre: { say: ["The whole summit? The shepherds, the drummers, the old women who knit?",
                      "She thinks it over. That week she gathers the five Heights villages in the square. They vote. The windmills become everyone's: each village sings in one, by turns, and the money is shared.",
                      "The Choir will hate me. But the Heights will eat evenly. Nobody had ever done that with the wind."] },
      tuya: { say: ["You ask Aspa to leave one windmill free for a night. You stand before the sails and sing something of your own, the first thing that comes out.",
                    "The next day, in the Meadow, in the Caves, at the Lake, people hum your song without knowing where it came from.",
                    "Now you sell too. Without charging, but you sell. What song was it? I have it in my head and I don't know what it says."] },
      dejar: { say: ["As they are. Fine. Tomorrow the Choir premieres a song. It'll sound across the whole Glade before noon.",
                     "The next day, the whole Glade sings the same thing. You too, without noticing, as you walk back."] },
    } },

    "e7-brisa": { who: { brisa: "Brisa, voice of the Choir" }, nodes: {
      a: { say: ["On the Choir's stone balcony, a woman of about thirty-five, her hair tied with colored ribbons, rehearses facing the wind. She has a voice that gets into your bones.",
                 "Brisa. I remember you. Or someone like you. I was little, and someone taught me something to sing into the wind. I haven't stopped since.",
                 "I'm the Choir's voice. I sing what sells. I want one thing: that the Heights never go down to beg again. Never. That's why I sing."],
           opts: ["“I taught you the lullaby. Do you still sing it?”", "“Yesquero paid you a coin a day.”", "“What do you sing when nobody pays?”", "“Sing me this week's song.”", "“Sing the same for everyone. For those who pay and those who don't.”"] },
      nana: { say: ["The lullaby. I sing it every night, alone, on the balcony, so the summit sleeps. I don't sell it. Nobody ever asked me for it. It's the only thing the Choir doesn't know I sing."] },
      moneda: { say: ["A coin. My first coin. I wear it around my neck. Yesquero got rich on moss and then told the Choir about the wind. That's how it all started.",
                      "I don't hold it against him. He taught me what my voice was worth. Since then I don't give it away."] },
      gratis: { say: ["Nothing. When nobody pays, I don't sing. I save my voice. A voice like mine wears out.",
                      "Well. The lullaby. But that doesn't count."] },
      cantar: { say: ["Brisa sings. It's a song about the Heights, about snow, about people who don't give up. It's beautiful. It makes you want to move up to the summit.",
                      "Then you see that, on the balcony below, a Meadow merchant listens to her sing another: about the Meadow, about lanterns, about people who don't give up. The same music. Other words.",
                      "Everyone wants to hear themselves. I give them that. Is that lying? I don't know. It's singing."] },
      igual: { say: ["The same for everyone? Then nobody will feel the song is theirs.",
                     "She tries it one afternoon. She sings the same words for the Meadow, the Hollow and the Heights. Half don't buy it. The other half sing it together, in three peoples at once.",
                     "I sold less. But today three peoples sang the same thing without fighting over the words. I don't know if it's good for business. I liked it."] },
    } },

    "e7-arpegia": { who: { arpegia: "Arpegia, who speaks with her hands", brisa: "Brisa, voice of the Choir" }, nodes: {
      a: { say: ["At the old summit lookout, where long ago someone hummed barefoot, a thin woman moves her hands facing the wind. She makes no sound. People pass and don't look at her.",
                 "(With her hands, slowly, so you can follow) Arpegia. This is how my name is said: two fingers falling like rain. I can't hear. I never could. The wind's songs don't stick to me.",
                 "(With her hands) My family kept promises in songs. I can't. So I keep them like this. A promise made with the hands doesn't depend on sound. The wind doesn't carry it off. Nobody sells it."],
           opts: ["Learn to say “I promise” with your hands", "Ask Brisa to translate what Arpegia says", "Greet her and leave"] },
      aprender: { say: ["You stay all afternoon. Arpegia teaches you: the open hand on the chest, then closed, then toward the other. “I promise.” You repeat it until you get it.",
                        "(With her hands, smiling) There. Nobody heard what you just did. Not even the Root. Only me. Now you have to keep it anyway. That's the hard part.",
                        "As you leave, you see her watching you from the lookout, her open hand on her chest."] },
      brisa: { say: ["Brisa climbs to the lookout reluctantly. She watches Arpegia's hands. She translates out loud.",
                     "She says my voice is lovely. That she hears it with her feet, when I sing loud. Not to believe my own song. That I... no. I'm not translating that.",
                     "Brisa leaves. Arpegia keeps moving her hands for a while, toward where she went."] },
      irte: { say: ["You nod to her. She returns the greeting with a gesture you don't understand. She keeps talking to the wind."] },
    } },

    "e7-coro": { who: { bordon: "Bordón, the Choir's treasurer", brisa: "Brisa, voice of the Choir", pregonero: "Pregonero, singer of squares" }, nodes: {
      a: { say: ["In the Choir's hall, three people count coins on a long table. The voice, the one who collects, and the one who sings in the squares. An old painting on the wall shows another three, many generations ago, voting with raised hands.",
                 "Bordón, treasurer. The Choir of Three governed the Heights by vote. Now it governs the Glade by song. They say the Heights shared out the verses, long ago. It used to be a lie. Now it's true, and we charge for it.",
                 "Pregonero, at your service. I sing them first, in the squares. If I sing it first, it sticks. And we get rich. We want you to be part of it. People believe you."],
           opts: ["Accept becoming a partner in the Choir", "“No.”", "“One free song a week, for everyone. That's my condition.”"] },
      socio: { say: ["Good. Your share.",
                     "He gives you a bag of coins. The next day, Pregonero sings in the Meadow square a song that names you, your creature, the Ford. It sticks. Everyone sings it.",
                     "Now you're famous. And the fame is ours. When you don't like what we sing, you'll have to sing it anyway. That's how it works."] },
      no: { say: ["No. Of course. You don't need the money.",
                  "Careful, eh. If you're not with the Choir, the Choir can sing about you. Whatever it likes. And it sticks just the same.",
                  "Brisa says nothing. She watches you leave with a face you can't read."] },
      gratis: { say: ["Free? One a week? That's half of what we make.",
                      "They argue all afternoon. Brisa votes yes. Pregonero votes no. Bordón counts coins and, in the end, votes yes.",
                      "One a week. Free. Brisa chooses it. If we go broke, I'll send you the bill."] },
    } },

    "e7-vado": { who: { brisa: "Brisa, voice of the Choir" }, nodes: {
      a: { say: ["Brisa comes down to the Ford. It's the first time you've seen her off the summit. She looks at your house, your creature, the water. She hums without noticing.",
                 "Every people in the Glade has its song. They bought it. The Meadow, the Hollow, even the Deep. The Ford has none. People pass through here and don't know what to sing.",
                 "The Choir will sell you one. I'll give you a good price. Or... I don't know. You could write one. I've never seen anyone write a song for their own home."],
           opts: ["Buy her a song for the Ford", "Write a song for the Ford", "“The Ford doesn't need a song.”"] },
      comprar: { say: ["You pay her. Brisa sings over the Ford's water, slowly. It's a song about a place where the river is crossed and people wait for each other. It's good. It sticks.",
                       "From that day, whoever passes the Ford hums it. Your creature too. It falls asleep to it.",
                       "Now it has a song. It's mine, but it's yours. That's how bought songs are: they never quite become your own."] },
      escribir: { say: ["You sit on the bank with Brisa all afternoon. You write. You cross out. It doesn't rhyme. Brisa laughs, then goes quiet, then helps you with a word.",
                        "At dusk, you sing it. It sounds bad. Your creature sings it with you, worse. Brisa doesn't sing it into the wind: she says the wind doesn't deserve it.",
                        "It doesn't stick. Nobody will hum it without meaning to. Those who want to will sing it. That's strange. That's good."] },
      sin: { say: ["No song? Then what will passers-by sing?",
                   "Whatever they like, you tell her. Brisa looks at the water a long while.",
                   "Whatever they like. For years nobody has sung what they like. They'll sing what we sold them somewhere else. But here, at least, we didn't put it there."] },
    } },

    "e7-verso": { who: { bordon: "Bordón, the Choir's treasurer" }, nodes: {
      a: { say: ["Bordón calls you to the Choir's hall. On the table there's a sheet with a verse written on it. It doesn't rhyme. You recognize it.",
                 "The ninth verse. The pact's condition. With the windmills, in a week the whole Glade sings it. Everyone knows it, everyone repeats it, nobody forgets it. Imagine.",
                 "And if it becomes the song of the moment, we can charge. For singing it at a wedding, at a wake, at a pact. The Choir would own the verse that holds up the Glade. Shall we?"],
           opts: ["“How did you get it, if after the Veil nobody remembered it?”", "“It was said aloud when the names were spoken. Why sell it?”", "“The verse was kept inside a name. Where did this come from?”", "Let them sell it", "Stop it"] },
      velo: { say: ["Nobody remembered it. Stone did. In the Caves there's an old wall with drum verses. There it was, in a corner, with a signature nobody can read."] },
      nombres: { say: ["Because it was said, yes. Once. Everyone heard it and nobody learned it. It doesn't rhyme, it has no music. Things that aren't sung are forgotten. We gave it music. That's worth something."] },
      guardado: { say: ["This isn't the verse. It's what we think it is. Three tavern versions, mixed. Someone has the real one. A Tides woman, they say. We're looking for her.",
                        "When we find her, we'll have the good one. Meanwhile, we sell this."] },
      vender: { say: ["Good. It's a good deal for everyone.",
                      "A week later, the ninth verse sounds across the whole Glade, with a catchy tune. Children skip to it in the square. Couples sing it when they marry and pay the Choir.",
                      "In the Heart, the Root stirs. Something that was a condition is now the song of the moment. Nobody knows if that binds it tighter or sets it loose."] },
      impedir: { say: ["You grab the sheet and tear it up in front of Bordón. He doesn't move.",
                       "I have copies. But I understand. If you oppose it, people will find out, and a song the Keeper hates doesn't sell well.",
                       "I'll keep it. I won't burn it. Someday someone will want to buy it for more than today. Patience."] },
    } },
  });

  add("aurora", {
    "e7-plaza": { who: {}, nodes: {
      a: { say: ["In the Meadow's big square, a hundred people sing the same song while doing other things: selling bread, sweeping, arguing. The song is this week's. It's about how lovely the Meadow is.",
                 "A Quarter woman, sitting on a bench, tries to sing something else. This week's comes out. She tries again. This week's again. She covers her mouth.",
                 "“I had a song of my own. From when I was little. It won't come out. It went under this one.”"],
           opts: ["Propose a night when everyone sings a song of their own", "Help her remember hers, one word at a time", "“Let the Quarter buy the next song and choose it.”"] },
      noche: { say: ["You talk with the Quarter neighbors. That night, in the square, they gather. The rule is simple: nobody sings the Choir's. Everyone their own.",
                     "At first nothing comes. Then an old man sings something of his mother's. A girl makes one up. The woman on the bench finds three words of hers. The square sounds awful: a hundred songs at once.",
                     "It's the loveliest noise you've ever heard in the Meadow. The next day, the Quarter repeats the night. It gives it a name: “the night of voices.”"] },
      recordar: { say: ["You sit with her. You ask what her house was like, her mother, what the kitchen smelled of. Little by little words come. One. Two. A tune.",
                        "In the end she sings it whole, softly. It's a badly rhymed lullaby. She cries.",
                        "“I have it. I'll sing it to myself every morning before going out. So this week's doesn't cover it.”"] },
      comprar: { say: ["The Quarter saves coins for a whole week. It buys a song from the Choir and chooses the words: it's about the long table and people who eat together.",
                       "The following week, the whole Meadow sings the Quarter's song. The Houses too, without noticing. It annoys them when they notice."] },
    } },

    "e7-tarara": { who: { tarara: "Tarará, Meadow girl" }, nodes: {
      a: { say: ["In a Meadow house, a nine-year-old girl sings nonstop, sitting on the bed. Her mother covers her mouth with her hand. The girl keeps singing through the hand.",
                 "Tarará. My name's Tarará. I can't stop. Every song on the wind sticks to me. All at once. I sing awake. I sing asleep. I want silence. Once.",
                 "The mother says there's still forgetting shadow in the Hollow, in jars. That with a little, the girl would forget all the songs. All of them. Even the lullaby."],
           opts: ["Take her to the Hollow, to the forgetting shadow", "Teach her to sing with her hands, like Arpegia", "“Let her sing. It's her voice.”"] },
      olvido: { say: ["You take her to the Hollow with her mother. An old shadow opens a jar. Tarará breathes. She falls silent, for the first time in years.",
                      "...",
                      "Silence. The girl smiles. The next day she knows no songs. Not the lullaby either. Her mother sings it to her at night and Tarará looks at her like a stranger."] },
      manos: { say: ["You teach Tarará what Arpegia taught you: “I promise,” “silence,” “thank you.” Then you take her up to the summit, to the lookout.",
                     "Arpegia takes her hands. She teaches her to sing with them: to move her hands to the rhythm of what sounds inside her, instead of opening her mouth. Tarará tries. Her mouth closes. Her hands sing.",
                     "(With her hands, clumsy, happy) Silence. I have silence outside. Inside it goes on. But outside, silence."] },
      cantar: { say: ["Sing? But my throat hurts. My head hurts.",
                      "The mother glares at you. Tarará keeps singing. That night she sings in her sleep, all the songs of the Glade, mixed, one after another.",
                      "The neighbors gather at the window to listen. Some cry. They say she sings songs not heard for generations. She doesn't know where she gets them."] },
    } },

    "e7-pregonero": { who: { pregonero: "Pregonero, singer of squares" }, nodes: {
      a: { say: ["On the steps of the Lantern Houses, a man in a yellow jacket sings at the top of his lungs, with a voice like thunder. People stop to listen.",
                 "Pregonero, the first to sing what's going to stick. Today I sing for the Lantern Houses. They paid me. “The Houses that shine, the Houses that give.” In a week, the Quarter will be singing it.",
                 "I sing what I'm paid to. What else can I do? If I don't sing it, someone else will. Better me, I sing well."],
           opts: ["Convince the Houses to make their song belong to the whole Meadow", "Pay him to sing the truth about the Houses", "Let him sing"] },
      casas: { say: ["You speak with the Lantern Houses in their parlor. You tell them what happens with bought songs: they stick, they cover. That the Quarter sings them without wanting to and hates them for it.",
                     "An old man of the Houses, with his grandfather's worn book under his arm, listens. He says in his family there was one who wrote the truth when nobody wanted it. That that can't be bought.",
                     "The next day, the Houses pay Pregonero to sing a song about them with no words. Just music. Let everyone put in what they like. The Quarter puts in insults. The Houses laugh. It's the first time."] },
      pagar: { say: ["The truth? Costs the same. I sing what I'm paid to, I told you.",
                     "He sings, at the top of his voice, the story of the winter firewood. The Houses throw him off the steps. Pregonero leaves laughing, with your coins.",
                     "Tomorrow they'll pay me to sing something else louder. You made me earn twice. Thanks."] },
      dejar: { say: ["Pregonero carries on. After a while, the whole square sings “the Houses that shine.” A Quarter woman sings it as she sweeps, looking disgusted."] },
    } },
  });

  add("crater", {
    "e7-compas": { who: { martinete: "Martinete, Guild foreman" }, nodes: {
      a: { say: ["In the Great Forge a fast work song plays, coming from a wooden box with a pipe that opens to the wind. The workers hammer to the beat. They've been hammering fourteen hours.",
                 "Martinete, foreman. The Guild bought the song. With it nobody gets tired. Well, they do, but they don't notice. We produce double.",
                 "A young worker faints by the anvil. The others keep hammering to the beat. Martinete drags him aside without stopping his humming."],
           opts: ["“Let a resting song play at noon.”", "Break the song box", "“The Guild pays more for more hours. Let them go on.”"] },
      descanso: { say: ["A resting song? A song that makes you stop?",
                        "You ask Brisa, on the summit, for a slow song. She sings it into the wind at noon. In the Forge, the hammers lower on their own. The workers sit. They eat.",
                        "One hour. Nobody wanted to stop and nobody could. Now everyone stops at once. The Guild will protest. The workers won't. Neither will I."] },
      romper: { say: ["You smash the box with a forge hammer. The music cuts off mid-beat. The workers freeze, hammers in the air.",
                      "Then, one by one, they sit on the floor. They look at their hands. Some cry from a tiredness they hadn't felt.",
                      "The Guild will send another box tomorrow. But today they realized how much they were working. No box takes that away."] },
      seguir: { say: ["More hours, more pay. That's how it is.",
                      "The hammers go on. The fainted worker wakes, stands, goes back to the anvil. He hums."] },
    } },
  });

  add("forest", {
    "e7-setos": { who: { ligustro: "Ligustro, of the Moss Council" }, nodes: {
      a: { say: ["At the edge of the Forest, the Council planted very tall hedges, tightly packed, with black leaves. On the other side, the deep wind blows with its songs. On this side, nothing.",
                 "Ligustro, of the Moss Council. The hedges don't let the wind through. Or the songs. The Forest doesn't buy. The Forest doesn't let anything stick to it.",
                 "The problem is that now nothing can be heard. Not the birds. Not the Root in the Long Silence. The hedges are too good."],
           opts: ["“Open a gap. Just one, to listen.”", "“Plant them higher.”", "Pull up the hedges"] },
      hueco: { say: ["They cut a gap in the hedge, the size of a door. A little wind comes through, a scrap of song, a bird.",
                     "The Forest folk stand before the gap to listen. Some leave humming. Others cover their ears and come back.",
                     "A gap. That's how the Forest listens: a little, carefully, choosing. That's what we did in the Long Silence, before. We had forgotten."] },
      altos: { say: ["The hedges grow another meter. The Forest is left in a cotton silence. Children speak softly without being asked to.",
                     "No bought songs. None. And no birds. I suppose that's the price."] },
      arrancar: { say: ["You pull up the hedges with the Forest's young folk, a whole week. The roots go deep. At last, the wind bursts in, with every song in the Glade.",
                        "That night, the whole Forest sings this week's song. Ligustro too. He covers his mouth with his hand, furious."] },
    } },
  });

  add("hollow", {
    "e7-sombras": { who: { sigilo: "Sigilo, landless shadow" }, nodes: {
      a: { say: ["In the Hollow, on the edges of the dry wells, homeless shadows live. They all sing. Low, nonstop, like a hum. When you come near, they sing louder.",
                 "Sigilo. Landless shadow. We sing so nobody names us. If there's a song, the name can't be heard. If it can't be heard, they can't use it on you. Our mothers taught us.",
                 "We spend everything on songs. More than on bread. A song is a home you can wear. It's the only one we have."],
           opts: ["“Your grandmothers spoke their names aloud. That's why the Court scattered.”", "Ask the Hollow to give them a street of their own", "Sing with them", "“Tell me your true name. I won't use it on you.”"] },
      nombres: { say: ["They spoke them. Yes. And then they were driven out of everywhere with the name on them, like a sign. That's why we sing. So the sign can't be read.",
                       "The truth was good for the Glade. For us it was being left out in the cold."] },
      calle: { say: ["You go to the Hollow's council. They argue two days. In the end they give them a street, the oldest one, by the middle well. It's little. It's theirs.",
                     "The first night on the street, the shadows don't sing. They sleep. The Hollow's silence can be heard for the first time in years.",
                     "A real home. A street. I don't need the song to be inside something anymore. Now I sing it when I want to."] },
      cantar: { say: ["You sit with them and sing. The song is slow, wordless, a hum that rises and falls. After a while you don't know where your voice ends and theirs begins.",
                      "Now you're hiding too. It's nice, isn't it? Nobody sees you. Nobody asks you for anything."] },
      nombre: { say: ["Sigilo stops singing. The others too, suddenly. She looks at you a long while.",
                      "No. You won't use it on me. But someone else will, if they hear it. Thank you for asking. Nobody asks: they rip it out of you.",
                      "She starts singing again. Lower."] },
    } },
  });

  add("lake", {
    "e7-bajoagua": { who: { albufera: "Albufera, of the Tides" }, nodes: {
      a: { say: ["At Mirror Lake, the Tides folk dive in groups, all together, and stay under a long time. Bubbles rise to the surface, in rhythm.",
                 "Albufera, of the Tides. My grandmother learned to swim with Ondina. We sing underwater. The wind doesn't reach the bottom of the lake. What's sung down there is ours. It doesn't stick to anyone.",
                 "Up above nobody understands it. They say we make fish noises. The Choir came to buy it, once. It wanted to know what we sing. We didn't tell."],
           opts: ["Dive with them and listen", "“The Choir would pay well. Sell it one.”", "Stay on the shore"] },
      abajo: { say: ["You breathe deep and go down with them. Below the water is green and still. Albufera sings with her mouth closed. The bubbles rise in a slow rhythm. You feel it in your chest more than your ears.",
                     "It's the lullaby. But different: slower, with notes you don't know, as if under the water it had been kept another way.",
                     "Now you've heard it. Down here. Don't take it up. Up there it sticks and breaks. Here it stays whole."] },
      vender: { say: ["Sell it? The only thing the wind didn't take from us?",
                      "In the end they sell an old fishing song. The Choir loads it onto the wind. A week later, the whole Glade sings a Tides fishing song, fast, cheerful, without bubbles.",
                      "It isn't ours. It's one that looks like it. That's how everything sells: by looking like it."] },
      orilla: { say: ["You stay on the shore watching the bubbles. They rise, burst, rise. After a while the Tides folk come up, breathing hard, and dry off without talking about what they sang."] },
    } },

    "e7-guardiana": { who: { albufera: "Albufera, of the Tides" }, nodes: {
      a: { say: ["Albufera takes you at night to a hut on a small island in the lake. Inside there's a shadow woman of about forty, lips pressed tight. She doesn't greet you.",
                 "Don't ask her name. Ever. Her name is the verse. They gave it to her as a girl, before the nine peoples. She's lived with us since. She has a daughter.",
                 "The Choir is looking for her. It sent people to the lake. If they find her, they'll make her sing. Or her daughter. A verse like that, stuck on the wind, is worth more than all the windmills."],
           opts: ["Hide them farther away, in the Deep", "Teach them to say the verse with their hands, without sound", "“Let her sing it once, free. Let her stop carrying it.”"] },
      esconder: { say: ["That same night you take the woman and the girl toward the White Deep, by boat and then on foot. Grumo, the eldest dreamer, gives them an ice bed in an old hall.",
                        "The wind doesn't reach there. The Choir doesn't. Nobody does. The girl will grow up in the cold, among dreamers. I don't know if that's saving her."] },
      manos: { say: ["You show the woman Arpegia's gestures. She watches. She moves her hands, slowly, like someone trying a key.",
                     "Then she does something you didn't teach her: she says her name with her hands. The whole verse. Without sound. You see it and don't understand it. She cries.",
                     "She said it. For the first time in her life. Nobody heard it. Not the wind, not the Choir, not the Root. Only we saw it. Now she knows she can."] },
      cantar: { say: ["Sing it? Let it go? If she sings it, it stops being hers. It's everyone's. And the Choir loads it onto the wind the next day.",
                      "The woman looks at you. She opens her mouth. She closes it. She shakes her head, slowly.",
                      "As you leave, you hear her humming something behind the door, very softly. It isn't the verse. It's the lullaby. The one she sings when she can't say her name."] },
    } },
  });

  add("caves", {
    "e7-ecotorcido": { who: { cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["In the Caves, the echo repeats the wind's songs over and over, day and night. But each time it repeats them, it changes them a little. What goes in as a love song comes out as an insult.",
                 "Cuarcita, of the Hondura. My mother was Mica. She carved what others erased. I carve what the echo twists. I don't know anymore which is the true song and which the twisted one.",
                 "The worst part is that the twisted ones stick better. The folk up above already sing them twisted. They fight over lines the echo invented."],
           opts: ["Carve the original words of each song, beside the echo", "Wall up the echo gallery", "“Sell the twisted ones. They stick better.”"] },
      grabar: { say: ["For a week, with Cuarcita, you listen to each song as it comes in, before the echo touches it, and carve it on the wall, word by word.",
                      "Beside it, Cuarcita carves what comes out. Two columns. People come down to compare. Some laugh. Others realize why they fought.",
                      "Now you can see what the echo did. My mother used to say: stone doesn't choose. But you can set what was beside what remained."] },
      tapar: { say: ["They wall up the gallery's mouth with stones. The echo fades on the other side, slowly, like someone falling asleep mid-sentence.",
                     "Quiet. Now songs don't get twisted here. They get twisted somewhere else, in people's heads. That can't be walled up."] },
      vender: { say: ["Sell? Us? The Hondura doesn't sell memory.",
                      "In the end a young picker does it in secret: he takes three twisted songs to the Choir. They stick within a week. One is an insult to the Tides. There are fights on the shore.",
                      "The Hondura sold something. For the first time. And it was the worst thing we had."] },
    } },
  });

  add("deep", {
    "e7-suenos": { who: { grumo: "Grumo, eldest dreamer" }, nodes: {
      a: { say: ["In the Deep's dreamers' hall, people wake up empty, dry-eyed. A man in his thirties, his hair white with frost since childhood, walks among the beds.",
                 "Grumo. Eldest dreamer. We used to dream what others forgot. Now the wind takes it from us at night. It rises through the cracks in the ice. In the morning, on the summit, someone sings what we dreamed.",
                 "I don't know if it's a relief or a theft. The dreamers don't cry anymore. But they don't remember anything either. They wake up like an unmade bed."],
           opts: ["“Did Sopor feel it too?”", "Seal the cracks in the ice", "“Let it take them. You've carried enough.”", "Have someone sing the lullaby in the hall every night, on watch"] },
      sopor: { say: ["Sopor. I remember when she wouldn't wake. And when she woke to the lullaby. She died old, telling one dream each morning. She said dreams belonged to the Root and had to be given back.",
                     "But not like this. Not by the wind, for the Choir to sell."] },
      tapar: { say: ["They seal the cracks with packed snow and water that freezes. The wind stops coming into the hall. That night, the dreamers cry in their sleep again.",
                     "The dreams are back. The crying is back. At least they're ours. Someone has to cry them, and we don't want a stranger singing them on the summit."] },
      dejar: { say: ["Let it take them. Yes. We're tired.",
                     "The wind keeps coming in. The dreamers sleep like stones. On the summit, the Choir premieres a song that sounds very much like crying."] },
      nana: { say: ["You set up watches. Each night, one dreamer stays awake and sings the lullaby softly, sitting by the cracks in the ice.",
                    "The wind keeps coming in, but when it passes through the lullaby, it leaves slower. The dreams stay a little longer. The dreamers wake with something, even if just a piece.",
                    "A piece. That's what we wanted. Not all, not nothing. The Deep was always about sharing out."] },
    } },
  });

  add("heart", {
    "e7-talon": { who: {}, nodes: {
      a: { say: ["In the Heart, among the statues, the wind comes out of a crack at the foot of the Root, where the Root sinks in like a heel. It comes out with a single long note that never changes.",
                 "Nobody buys it. The Choir tried it in the windmills: it doesn't stick. Nobody knows how to sing it. It's too long for a throat.",
                 "If you don't move, you feel it in the ground, in your teeth, in your creature's chest."],
           opts: ["Try to sing the note, with your creature", "Listen without doing anything", "Take the note to the Choir"] },
      cantar: { say: ["You open your mouth and sing the note. You run out of breath right away. Your creature carries on, with its small voice. When it tires, you take over. Like that, by turns, a good while.",
                      "At some point, the Root's note and yours meet. The ground stops trembling. For a second, the wind falls silent.",
                      "Then it comes back. But your creature stays looking at the crack like someone who heard its name."] },
      escuchar: { say: ["You sit among the statues and listen. The note doesn't change. After a while, you start to hear things inside it: voices, pieces of old songs, a drum, a lullaby.",
                        "It isn't one note. It's all of them at once. Everything the Glade has ever sung, pressed into a single sound."] },
      coro: { say: ["You describe the note to Bordón, in the Choir's hall. He writes it down. Brisa listens from the door.",
                    "“It doesn't sell,” says Bordón. “We tried it.” Brisa says nothing. That night, from the balcony, you hear her try to sing it. Her voice breaks."] },
    } },

    "e7-fiesta": { who: { pregonero: "Pregonero, singer of squares" }, nodes: {
      a: { say: ["The Choir throws a festival in the Heart. Each people brings its bought song and sings it before the statues, by turns, louder than the one before.",
                 "Nine peoples, nine songs, one Choir! Whoever sings loudest wins. And the prize is a new song, free, that nobody else will have.",
                 "The songs clash in the air. The Root, beneath the statues, creaks. There's something in the creaking that sounds like a complaint."],
           opts: ["Sing the heel's note in the middle of the festival", "Ask for a minute of silence", "Let them carry on"] },
      nota: { say: ["Amid the noise, you stand before the heel's crack and sing the long note, with your creature. At first nobody hears you.",
                    "Then someone falls silent to listen. And another. The bought songs die out one by one. The note remains. And, beneath it, the ground stops creaking.",
                    "Well. That one doesn't sell. But it silences all the others. Now that's a song."] },
      silencio: { say: ["You climb onto a statue's base and ask for a minute of silence. They laugh. You insist. In the end, out of tiredness, they fall quiet.",
                        "One minute. The wind keeps its note. The Root stops creaking. Someone, at the back, cries without knowing why.",
                        "Then the festival goes on. But quieter."] },
      seguir: { say: ["The festival goes on until dawn. The Meadow wins, with a song about lanterns. The Root creaks all night.",
                      "In the morning, among the statues, there's a new crack. Small. Another wind comes out of it, with another note."] },
    } },

    "e7-final": { who: { brisa: "Brisa, voice of the Choir", arpegia: "Arpegia, who speaks with her hands", bordon: "Bordón, the Choir's treasurer" }, nodes: {
      a: { say: ["The Singing Root falls, and from the heel comes a strong wind, full of every song in the Glade at once. The statues hum. Before them stand Brisa, Bordón and Arpegia.",
                 "It's all there. If we load the windmills with one song, just one, and the whole Glade sings it to the Root, the Root falls asleep. Because it has to, but it sleeps. Peace, sung.",
                 "Or the windmills are broken. All of them. The wind goes out ownerless. Songs stop being worth anything. I stop being worth anything. I don't know if I want that. I know it's fair.",
                 "(With her hands, and Brisa translates, slowly) There's a third. Promising without sound. Let the peoples promise each other things with their hands. The Root won't hear it. But they'll keep it. For that, all nine must be here."],
           opts: ["“What happens if the whole Glade sings one single song?”", "“What happens if the windmills are broken?”", "“What happens with promises the Root doesn't hear?”", "Have the whole Glade sing one single song", "Break the windmills", "Teach the Hand Song to the nine peoples"] },
      q1: { say: ["The Root sleeps. The squares sing the same, every day, to keep it asleep. Nobody chooses what to sing. But nobody is afraid.",
                  "And in every square something will remain. The summit elders say so: when the Root is forced to sleep, stars are born that don't speak. Mute. Full of promises nobody wanted to make."] },
      q2: { say: ["The wind belongs to everyone again. And to nobody. Anyone sings what they like, and it sticks anyway, for a while. Rumors will run ownerless. Nobody will know what to believe.",
                  "And nothing will be worth anything. Not songs, not lullabies. If everything sticks, nothing matters."] },
      q3: { say: ["(With her hands) The Root listens to sound. It always listened to that: the song, the lullaby, the verse. What makes no sound doesn't reach it.",
                  "She says the peoples will have pacts between them the Root doesn't know about. That it can be good. Or that the Root, one day, will find out it was left outside."] },
      unico: { say: ["Bordón gives the order. Brisa sings in all twelve windmills at once. One single song, slow, simple. The wind carries it across the whole Glade in one night.",
                     "In the morning, in every square, people sing it unable to stop. Toward the Heart. The Root goes still, like a child sung to too loudly.",
                     "In the Meadow square a small star appears, dull, floating over the fountain. It doesn't shine. It says nothing. A week later there's one in every square.",
                     "It sleeps. We did it. I don't have to change songs depending on who's listening anymore. Now everyone hears the same one. And I didn't choose it."] },
      libre: { say: ["You climb to the summit with Brisa. She takes the axe first. They cut the ropes of all twelve windmills, one by one. The sails spin wildly and stop.",
                     "The deep wind passes over the summit with nobody singing into it. It carries dreams, noises, half-songs. It sticks a while and goes.",
                     "The business is over. And the government. Tomorrow, anyone sings anything, and the Glade believes it for a day.",
                     "I'm worth nothing now. What a relief. And how frightening."] },
      manos: { say: ["The nine arrive. The Quarter with its night of voices, the Houses with their wordless song, the Fire with its hour of rest, the Forest with its gap in the hedge, the Heights with their shared windmills, the shadows with their street, the Tides dripping wet, the Hondura with its two columns, the Deep with its lullaby watch.",
                     "Arpegia stands in the center. She teaches them: the open hand on the chest, closed, toward the other. “I promise.” The nine repeat it, in silence, face to face.",
                     "The wind keeps blowing with all its songs. But between the peoples something passes that the wind doesn't carry. The Root, below, hears nothing. It stirs, uneasy, like someone who knows they're being talked about in another room.",
                     "(With her hands, and this time everyone understands) There. Now keep it. That's the hard part."] },
    } },
  });


  /* ==================== Delivery 2: the Meadow, the Crater and the Forest ==================== */

  /* ---------- Aurora Meadow: the sung election, the song school, the hate song, Tarará asleep, Pregonero's house, the singing lantern, the silence market and the long table ---------- */
  add("aurora", {
    "e7-eleccion": { who: { hogaza: "Hogaza, of the Quarter", quinque: "Quinqué, of the Lantern Houses" }, nodes: {
      a: { say: ["In the Meadow Council square there are two platforms. On one, a Quarter baker with flour on her arms. On the other, a young man from the Houses with a lantern embroidered on his jacket. Behind each of them, someone sings.",
                 "Hogaza, of the Quarter. Tomorrow the Council is chosen. Nobody votes by hand anymore: whoever has the song that gets sung the most wins. We chipped in for one. They bought three.",
                 "Quinqué, of the Lantern Houses. It's not my fault people sing ours. It's a better song. That's how it works now. It used to be whoever shouted loudest won. Now it's whoever sings best. That's progress."],
           opts: ["“Vote by raised hands, like before.”", "Help the Quarter write a song of its own, without buying it", "“Let the best song win. That's how it is now.”"] },
      mano: { say: ["By hand? That's for grandparents. People don't know how to raise a hand without singing anymore.",
                    "You talk to the old Council. They agree to try: a vote by raised hands, in silence, with no song. The square feels strange, hushed. People look at each other, unsure.",
                    "Hogaza wins by eleven hands. Quinqué steps down from his platform and shakes her hand. The next day, the Houses buy a song that says the vote was rigged. It sticks."] },
      barrio: { say: ["You spend the night in the Quarter bakery. Together they write a song about morning bread and the people who get up early. It doesn't quite rhyme.",
                      "The next day, the Quarter sings it in the square, with no wind, no windmill. It sounds tiny next to the Houses' three songs.",
                      "We lost. But we sang it ourselves. And the ones who sang it were the ones who wanted it, not the ones who heard it. Next time, more people will want it."] },
      cancion: { say: ["Quinqué wins. His song sounds across the whole Meadow for three days. On the fourth, the Choir sells a new one and nobody remembers who won.",
                       "Whoever buys, governs. And whoever buys is whoever already had. That's nothing new. What's new is that we sing it."] },
    } },

    "e7-escuela": { who: { retahila: "Retahíla, Meadow teacher" }, nodes: {
      a: { say: ["In the Meadow school, the children sing their times tables, the names of the nine villages, the history of the Glade. All to the wind's music. All stuck.",
                 "Retahíla, teacher. My grandmother taught here, with a pencil in her hair. I teach by singing. They learn everything in a week. They never forget it.",
                 "The trouble is they only know what gets sung. If I ask them something with no song, they go blank. And the history they sing is the one the Choir wrote."],
           opts: ["“Mimbre took her pupils to read the walls of the Caves.”", "“Teach them one thing a week without a song.”", "“Let them make up the songs for what they learn.”", "“If they learn, they learn. Carry on.”"] },
      mimbre: { say: ["My grandmother. Yes. They say she annoyed every parent. That the children came home asking questions.",
                      "Now the children don't ask. They sing. The parents are happy. That scares me."] },
      sin: { say: ["Retahíla tries it. One day a week, class is silent: they read, they ask, they argue. The children get bored. They get angry. One cries.",
                   "After a month, a girl raises her hand in the sung class and asks: “What if the song is wrong?” Retahíla has no answer.",
                   "One question. In a month. My grandmother had ten a day. It's a start."] },
      inventar: { say: ["The children make up songs about what they learn. They're bad. Off-key. One about the Lake says the water is made of cheese.",
                        "But they made them up, and to make them up they had to understand. A boy from the Tides corrects the cheese one: the Lake's water is cold, and once it froze.",
                        "They argue over the lyrics. That's learning. Nothing sticks to them: they have to decide."] },
      seguir: { say: ["Yes. They learn. Fast and well.",
                      "In the yard, the children sing the history of the Glade. It says the Choir brought plenty to the Heights. It says nothing about the windmills. Nobody asks."] },
    } },

    "e7-cancionodio": { who: { pregonero: "Pregonero, singer of squares" }, nodes: {
      a: { say: ["A new song has stuck in the Meadow, catchy, cheerful. It's about “the nameless ones,” “the ones who hide by singing,” “the ones who steal at night.”",
                 "Last night, three Meadow boys beat up a shadow at the edge of the Hollow. They were singing the song while they hit him.",
                 "I sang it first, yes. They paid me. I don't know who: a man in a hood came, from the Houses or the Guild, I don't know. What do you want me to do? It's already on the wind."],
           opts: ["Write another song to drown it out", "Find out who paid for it", "Ask Brisa to sing the song once more, but with different words", "“It's just a song.”"] },
      tapar: { say: ["With Pregonero you write a song about a shadow who sings so they'll leave her alone. It's sad. It isn't catchy.",
                     "Pregonero sings it in the square, for free, for the first time in his life. People listen. They don't hum it. But the other one goes quiet for a while.",
                     "It didn't stick. But they listened. I didn't know that either: that you can listen to a song without it sticking. I felt ashamed. I don't know of what."] },
      quien: { say: ["You ask at the Choir. Bordón won't tell you. In the end, for money, he shows you the book: three Houses families and a Guild foreman paid for it together.",
                     "You say it out loud in the Meadow square. The Houses deny it. The foreman doesn't. He says the shadows took work from his brother.",
                     "Now everyone knows who paid. The song is still sung all the same. But it isn't nobody's anymore. It's theirs. That weighs differently."] },
      brisa: { say: ["You tell Brisa. She stays silent a long while. That night, at the windmills, she sings the same music with other words: the shadow doesn't steal, the shadow sings so it won't be afraid.",
                     "The next day, the Meadow hums the music with both sets of words mixed up. The boys don't know which to sing. They stop.",
                     "Brisa sang for free. She'd never done that. Bordón is furious. I... I'm happy. Don't tell anyone."] },
      nada: { say: ["Just a song. That's what I say. And I get paid.",
                    "The song goes on for a month. The shadows stop coming to the Meadow. When the Choir sells another, the hate song is forgotten. What the boys did is not."] },
    } },

    "e7-tararasueno": { who: { tarara: "Tarará, Meadow girl" }, nodes: {
      a: { say: ["Outside Tarará's house, at night, there are people. Lots of them. Sitting in the street, listening at the window. The girl sings in her sleep: ancient songs, from generations nobody remembers.",
                 "An old woman recognizes a lullaby of her great-grandmother's. A man weeps at a lamplighters' song nobody has sung since the Black Sap.",
                 "(awake, in the doorway, hollow-eyed) Tarará. Have you come to hear me sleep? The Choir came yesterday. They want to put a windmill next to my bed."],
           opts: ["“Don't let the Choir in.”", "Write down in a notebook what she sings asleep", "Let the Choir put up the windmill"] },
      coro: { say: ["You talk to the neighbors. That night they keep watch at the door, in shifts. When the Choir people arrive, they don't let them through.",
                    "They're mine. The songs. Even if I don't know where they come from. While I sleep, they're mine. The neighbors say they like hearing me. I like being looked after."] },
      cuaderno: { say: ["You spend three nights on the floor of her room, with a notebook, writing by candlelight. Tarará sings. You take notes.",
                        "Twenty-three songs. One, the oldest, speaks of a pact and of someone who keeps watch. The words are broken, but half of it can be made out.",
                        "That's what I sing? I didn't know. Read it to me while I'm awake. I want to know what I say when I sleep."] },
      molino: { say: ["The Choir puts a small windmill on the roof of the house. When Tarará sings in her sleep, the wind carries off the old songs and lets them loose all over the Glade.",
                      "Within a week, the Meadow is singing songs from five generations ago without knowing why. Some people cry. The Choir charges. Her mother gets a coin a night.",
                      "They're not mine anymore. I dream them and they leave. I wake up with nothing."] },
    } },

    "e7-pregonerohija": { who: { pregonero: "Pregonero, singer of squares" }, nodes: {
      a: { say: ["Pregonero sits on the front steps of his house, his yellow jacket folded on his knees. His voice is hoarse from so much singing. A six-year-old girl tugs at his sleeve.",
                 "My daughter. She asks me to sing her something of mine. Something nobody paid me for. And I have nothing. I know a thousand songs. Not one is mine.",
                 "My father sang in the squares. My grandfather too. Always what they were paid for. What do I sing to a little girl who doesn't pay?"],
           opts: ["Help him write a song for her", "“Sing her the lullaby. It belongs to nobody.”", "“Sing her the one she likes best of the ones you sold.”"] },
      escribir: { say: ["The three of you sit on the steps. Pregonero tries. Square rhymes come out, advertising lines. He crosses them out.",
                        "In the end he writes four lines about a little girl who tugs at his sleeve. They're clumsy. He sings them softly, without his thunder voice.",
                        "It's the worst thing I've ever sung. And it's the only thing that's mine. I won't sell it to anyone. Not even you."] },
      nana: { say: ["The lullaby. Yes. My mother sang it. Nobody paid me for it.",
                    "He sings it. His thunder voice grows small. The girl falls asleep in his lap, on the steps, in the middle of the street.",
                    "It isn't mine. But it isn't theirs either. That's enough for now."] },
      vendida: { say: ["Pregonero sings her “the Houses that shine,” the one that stuck most this year. The girl sings it with him, happy. She knows it.",
                       "She knows it. Everyone knows it. I thought that was good. Now I don't know."] },
    } },

    "e7-farol": { who: { quinque: "Quinqué, of the Lantern Houses" }, nodes: {
      a: { say: ["At the top of the Houses' lantern tower, a young man measures the windows with a string. He wants to put a small windmill up there, to sing the Houses' song from the highest point in the Meadow.",
                 "Quinqué, of the Houses. The tower is empty. Full of old books, nothing else. My great-grandfather left them here. Nobody reads them. With a windmill, the tower is useful again: it shines with songs.",
                 "On a shelf there are three books tied with a cord. One says “the false one,” another “the true one,” the third is blank."],
           opts: ["“Tojo left those books for whoever came up to clean the lantern.”", "Read him the true book out loud", "“Put up the windmill. The tower is yours.”", "“Write in the blank book what's happening now.”"] },
      tojo: { say: ["Tojo? The one who wrote against his own uncle? In the Houses that name isn't spoken.",
                    "My grandmother said he was right. She said it quietly, in the kitchen. I never understood about what."] },
      leer: { say: ["You read him the true book: the winter firewood, the chairs burned in the Quarter, the portraits. Quinqué listens standing up, the string in his hand.",
                    "Nobody sings that. Nobody's going to buy it. That's why I didn't know.",
                    "He doesn't put up the windmill. He goes down with the book under his arm. A week later, someone in the Quarter says the young man from the Houses came to buy bread and apologized without saying why."] },
      molino: { say: ["Quinqué puts up the windmill. From the tower, the Houses' song sounds louder than all the rest. The Meadow sings it more than ever.",
                      "The books stay on the shelf, under the windmill. The wind shakes the dust off them every night."] },
      blanco: { say: ["Me, write? I don't know how to write books. I know how to buy songs.",
                      "In the end he writes one page. It says the Meadow sings what it buys, that his family buys more, and that he doesn't know if that's right. He signs it.",
                      "One page. My great-grandfather left a whole book blank. There's a lot missing. I'll keep going. Slowly."] },
    } },

    "e7-musgo": { who: { musguito: "Musguito, Yesquero's grandson" }, nodes: {
      a: { say: ["In the Meadow market, a skinny young man sells little balls of moss in jars. People put them in their ears and walk off happy, deaf.",
                 "Musguito, Yesquero's grandson. My grandfather got rich on moss and then on the wind. I sell the opposite: silence. Two coins, a day with no songs. It sells better than bread.",
                 "The odd thing is the people who buy silence are the same ones who buy songs. In the morning they plug their ears. In the afternoon they unplug them to hear the latest one."],
           opts: ["“Why not give it away, if it's Forest moss?”", "Buy a jar and try it", "“Your grandfather started all this.”"] },
      regalar: { say: ["Give it away? My grandfather taught me one thing: what people need, you charge for. What they don't need, you make them need.",
                       "He thinks about it. He watches an old woman counting coins for a jar and coming up short. He gives her one for free. He stares at his empty hand.",
                       "One. To whoever can't afford it. That way I don't go broke and I sleep better. Don't tell my mother."] },
      probar: { say: ["You put the moss in your ears. The Meadow switches off. You see people singing with their mouths open, without sound. They look like fish.",
                      "For the first time in weeks, the latest song isn't playing in your head. Something else is: your own voice, thinking.",
                      "You take the moss out in the afternoon. The latest song comes back all at once."] },
      abuelo: { say: ["My grandfather heard a girl singing on the wind and told the Choir. Yes. And he did it for money. And the money fed me.",
                      "I sell the cure for what he sold. That doesn't fix it. But it's something. What do you sell?"] },
    } },

    "e7-mesalarga": { who: { hogaza: "Hogaza, of the Quarter" }, nodes: {
      a: { say: ["In the Quarter's street stands the long table, the one for shared meals. But every chair has a colored ribbon: the color of the song bought by the family who sits there.",
                 "Hogaza, of the Quarter. The table used to be one. Now it's five tables pushed together. The red-ribbon folk sing theirs, the blue-ribbon folk sing theirs. They don't look at each other. They eat fast.",
                 "My mother said the long table was set up by the Quarter and the Houses together, without knowing why they'd hated each other. Now songs divide us, and we know very well why."],
           opts: ["“The table was set up when the Quarter and the Houses ate together.”", "Take off all the ribbons", "“One meal a week, without singing.”", "“Let each table have its song. That way there's peace.”"] },
      junta: { say: ["That's it. They ate together without remembering the hatred. My mother said it was strange and lovely. That the table was long because they didn't know where to put the edge."] },
      cintas: { say: ["That night, with Hogaza, you take all the ribbons off the chairs. In the morning, people arrive and don't know where to sit.",
                      "They sit mixed up. Someone starts singing their song. Another, theirs. They step on each other. They laugh. Someone passes the bread to the one with the other song.",
                      "One table again. Noisy. Badly sung. Mine."] },
      callar: { say: ["Hogaza proposes it out loud. One meal a week, at the long table, with no song. Some protest. Most give it a try.",
                      "The first day is awkward. You can hear chewing. The second, someone tells a story about their grandmother. The third, they laugh.",
                      "Without a song you have to talk. We'd forgotten how."] },
      cinco: { say: ["Peace. Yes. Each one in their own piece.",
                     "A month later, the red-ribbon folk move their table half a meter away. A gap is left. Nobody closes it."] },
    } },
  });

  /* ---------- Warm Crater: the Guild master, the strike song, the deaf of the forge, the apprentice, the bell, the accounts, the oldest worker and the anvil rhythm ---------- */
  add("crater", {
    "e7-azufre": { who: { azufre: "Azufre, Guild master" }, nodes: {
      a: { say: ["In the Guild office, a man with a gray mustache signs a contract bearing the Choir's seal. On the desk sits a new song box, bigger than the Forge's.",
                 "Azufre, Guild master. The Crater went hungry three times in a hundred years. With the work songs we produce double. We sell to the Heights, to the Deep, beyond the pass. Nobody in the Crater goes hungry now.",
                 "I know what you're going to say. That they work too much. Yes. They eat more too. Choose: fourteen hours and bread, or eight hours and nothing."],
           opts: ["“Ten hours, and the same pay.”", "“Let the workers choose the song.”", "“You're right. Let them carry on.”"] },
      diez: { say: ["Ten? With the same pay? That comes out of my profits.",
                    "You argue for an hour. In the end, Azufre runs numbers on a sheet of paper. He looks at them. He grunts.",
                    "Ten. For one year, and we'll see. If the Crater goes hungry, I'll come find you at the Ford with the bill."] },
      elegir: { say: ["Azufre agrees to let the workers vote on what song plays in the Forge. They pick a slow one, from the Tides, with bubbles. They work badly to it.",
                      "They produce half. They're happy. The Guild is going to lose money. I don't know if I care as much as I should."] },
      razon: { say: ["Thank you. Nobody says it. Everybody thinks it.",
                     "He signs the contract. The new box is taken to the Forge that same afternoon. It plays louder than the old one."] },
    } },

    "e7-huelgacantada": { who: { martinete: "Martinete, Guild foreman" }, nodes: {
      a: { say: ["In the Crater square, the workers want to strike. But when the work song plays, they lose the urge. Their legs carry them to the Forge on their own.",
                 "They want to buy a strike song from the Choir. One that makes them stop. The Choir says yes. The trouble is the Guild already bought another from the Choir that makes them go back. Both will play at once.",
                 "The Choir sells to both sides. And wins twice. I'm a foreman. I should be with the Guild. I don't know whose side I'm on."],
           opts: ["“Strike without a song. With your hands.”", "“Plug your ears with moss and stop.”", "“Buy the strike song.”"] },
      manos: { say: ["You teach the workers Arpegia's gesture: “I promise,” the hand on the chest. They do it face to face, in the square. Without a sound.",
                     "When the work song plays, their legs want to go. But they look at each other and remember the hand on the chest. They stay. They tremble. They stay.",
                     "They promised without a sound. The song can't drown it out. The first strike in the Glade that can't be heard. The Guild doesn't know what to do: there's nothing to answer."] },
      musgo: { say: ["They buy moss from Musguito, all he has. They put it in their ears and sit in the square. They hear nothing. Not the song. Not Martinete.",
                     "They stopped. Three days. They won an hour less a day. But now they can't hear each other. They argue in signs and fight more."] },
      comprar: { say: ["They buy the strike song. Both songs play at once in the Crater: one that says “stop,” another that says “go back.”",
                       "The workers take two steps toward the Forge, two toward the square. Like that all day. At night they're exhausted and they've done nothing.",
                       "The Choir got paid by both sides. We got nothing. Well, no: we learned that songs don't belong to the ones who buy them."] },
    } },

    "e7-sordos": { who: { martinete: "Martinete, Guild foreman" }, nodes: {
      a: { say: ["At the door of the Forge stand six old workers with their tools in a sack. They're deaf: years of hammering took their hearing. The work song does nothing to them.",
                 "They work eight hours. The others, fourteen. The Guild says they're slow. That they don't keep up. They were fired this morning.",
                 "One of the old men moves his hands. Another answers the same way. They talk among themselves in signs, quick, old, that nobody else understands."],
           opts: ["Greet them with Arpegia's gesture", "“They work a fair amount. The others, too much. Let them come back.”", "Take them to Arpegia, on the summit"] },
      arpegia: { say: ["You make the gesture: the open hand on the chest. The six old workers go still. One smiles and answers with another gesture, one you don't know.",
                       "They've spoken more with their hands than with their mouths for thirty years. They have words for “anvil,” “heat,” “tired,” “unfair.” Arpegia has others. They're alike.",
                       "There are more people who talk like that than I thought. I never looked at their hands."] },
      volver: { say: ["You go with Martinete to the Guild office. You show Azufre the accounts: the deaf workers make fewer pieces, but none come out wrong. The others, worn out, break one in five.",
                      "They're back. The Guild won't say it, but it knows that whoever works eight hours works better. What I don't know is what to do about the fourteen."] },
      cumbre: { say: ["They climb to the Heights. Arpegia receives them at the lookout. She moves her hands. The old workers answer. It takes them a while to understand each other. After that they don't stop.",
                      "Within a week, the six old workers and Arpegia have a hand language that mixes the two. They teach anyone who wants it. The first to learn are the workers' children.",
                      "They were thrown out of the Crater and built a language. No work song produces that."] },
    } },

    "e7-astilla": { who: { astilla: "Astilla, Forge apprentice" }, nodes: {
      a: { say: ["In a corner of the Forge, a ten-year-old girl polishes nails in time with the song. Her hands are covered in blisters. She hums. She smiles.",
                 "Astilla. Apprentice. I've been at it twelve hours. I'm not tired. Well, I am. But I don't feel it. The song won't let me feel it. It's nice.",
                 "She drops a nail. She picks it up without stopping her humming. She drops another. Her fingers are shaking."],
           opts: ["Take her outside, away from the song", "“Does your family know how many hours you work?”", "Let her work"] },
      afuera: { say: ["You lead her out by the hand. At the Forge door, away from the box, Astilla stops humming. She looks at her hands. She sits down on the ground all at once.",
                      "It hurts. Everything. My hands, my back, my eyes. Did it hurt the whole time? I didn't notice.",
                      "She cries for a while. Then she falls asleep right there, on the warm stone. Martinete covers her with his jacket and says nothing."] },
      familia: { say: ["My mom works fourteen. My dad too. I do twelve because I'm little. When I'm big, fourteen.",
                       "She says it happily, the way you'd say you're going to grow up. She keeps polishing."] },
      dejar: { say: ["Astilla keeps polishing. She hums. At the end of the shift, she faints over the nail table. Someone carries her home. The next day she comes back, humming."] },
    } },

    "e7-campana": { who: { azufre: "Azufre, Guild master" }, nodes: {
      a: { say: ["In the Guild yard, the master has a new bell, huge, of dark metal, still hot. The smiths look at it with fear.",
                 "Azufre, master. A bell to drown out the others' songs. When it rings, nobody in the Crater will hear anything but the Guild's song. Not the strike one. Not the Tides one. Nothing.",
                 "The old folk of the Deep say that long ago someone made bells to put the Root to sleep. This one isn't for that. This one is to wake up the workers."],
           opts: ["“The tied bells of the Deep put the Root to sleep, and people forgot its name.”", "“If it rings, let it be to mark the end of the shift.”", "Break the bell's clapper", "“Let it ring.”"] },
      fondo: { say: ["They forgot its name? Because of a bell.",
                     "He looks at the bell a long while. He puts his hand on it. It still burns.",
                     "This one is a different metal. But metal doesn't know what it's made for. Crisol taught me that, when I was a boy. I'd forgotten."] },
      turno: { say: ["Azufre thinks it over. That afternoon he hangs the bell in the Guild tower. It rings once, at ten hours of work. Loud. It drowns out every song.",
                     "In the Forge, the hammers stop. The workers look at each other. For a moment nothing sounds but the bell.",
                     "End of shift. A bell that makes people stop. It's the opposite of what I wanted. It works better."] },
      romper: { say: ["At night, with a hammer, you break the bell's clapper. It hangs mute in the yard.",
                      "In the morning, Azufre finds it. He doesn't shout. He knocks on it with his knuckles. It makes a dull sound, like a pot.",
                      "A mute bell. I'll leave it hanging. Let the smiths see it. So they remember someone said no."] },
      sonar: { say: ["The bell rings at noon. The whole Crater goes still for a second. Then everyone hums the Guild's song, louder than ever.",
                     "That night, in the Deep, the dreamers dream of bells. They don't know why."] },
    } },

    "e7-cuentas": { who: { martinete: "Martinete, Guild foreman" }, nodes: {
      a: { say: ["Martinete shows you the Forge's book of hours, in secret, in his kitchen. The columns climb month by month: ten, eleven, twelve, fourteen.",
                 "And the pay has been the same since the first month. They produce double. They earn the same. The Guild takes the double. And the Choir, for the box.",
                 "If I show this, they fire me. If I don't, I keep signing. What do I do with a book like this?"],
           opts: ["“Show it to the workers.”", "“Copy it onto the wall of the Hondura, so it stays.”", "“Keep it. Some day it'll be useful.”"] },
      obreros: { say: ["Martinete reads the book in the Crater square, at lunchtime. Month by month. The workers listen with bread in their hands.",
                       "The next day, nobody enters the Forge before the hour. Nobody stays after. The song plays the same. They cover their ears with their hands and leave.",
                       "They fired me. They'll hire me back in a month: there's nobody else who can keep the accounts. And now I keep them out loud."] },
      hondura: { say: ["You take the book down to the Caves. Cuarcita copies the columns onto a new wall, next to the winter firewood list.",
                       "There it stays. Next to the firewood. Same kind of accounting, another century. Someone will see both together and understand."] },
      guardar: { say: ["Some day. Yes. That's what my grandfather said about everything.",
                       "He puts the book under a floorboard. He keeps signing the hours. Every night, before sleeping, he lifts the board and looks at it."] },
    } },

    "e7-hornaza": { who: { hornaza: "Hornaza, the oldest worker" }, nodes: {
      a: { say: ["Next to a cold furnace, an eighty-year-old woman with arms full of spark scars watches the Forge in the distance. She hums nothing.",
                 "Hornaza. I worked seventy years in the Forge. I remember before the songs. You hammered to the rhythm of your own heart. Every anvil sounded different. It was a horrible, lovely noise.",
                 "Now they all hammer the same. The same blow, the same hour. It sounds like one single machine. I can't tell anymore which anvil is my grandson's."],
           opts: ["“What was the rhythm like before?”", "Ask her to teach hammering without a song", "Take her to the Forge so they can hear her", "“That's over. It's like this now.”"] },
      ritmo: { say: ["Each their own. I hammered in threes, with a pause. My husband, in twos. When we hammered together, it sounded like we were arguing. We argued, too.",
                     "In the long winter, my grandmother said, they hammered slowly so as not to waste strength. In the nail one, fast. Every age had its rhythm. This one has the Choir's."] },
      ensenar: { say: ["Hornaza gathers the apprentices one afternoon, at the cold furnace. She gives each a hammer. She tells them to find their own blow, without a song.",
                       "At first they all hammer the same, out of habit. Then one gets it wrong. Another laughs. Little by little, each finds their own. It sounds horrible.",
                       "There it is. That's how it sounded. Now each of them knows which anvil is theirs. Even if they go back to the song tomorrow, they know."] },
      forja: { say: ["You take Hornaza to the Forge. She stands in the middle, with her old hammer, and strikes an anvil to her rhythm: in threes, with a pause. Against the song.",
                     "The workers watch her. Some miss a beat. One, her grandson, follows her. Then another. For a while, there are two rhythms in the Forge.",
                     "He followed me. My grandson. Now I know which anvil is his: the one that got it wrong first."] },
      paso: { say: ["Over. Yes. Everything passes. I'll be passing soon too.",
                    "She keeps watching the Forge. As you leave, you hear her knock on the cold furnace with her knuckles, in threes, with a pause."] },
    } },

    "e7-yunque": { who: { martinete: "Martinete, Guild foreman" }, nodes: {
      a: { say: ["The Crater workers had an idea: to record on the wind the sound of the anvils, all of them, mixed together. A song of Fire, made by them. For the whole Glade to hear.",
                 "They want to take it to the windmills. Let it stick. Let the whole Glade know what the Crater sounds like. It's ours. We didn't buy it.",
                 "But if it sticks, in the Caves, at the Lake, in the Meadow they'll be hammering without hammers. Our song will do to them what the Guild's did to us."],
           opts: ["“Take it to the windmills.”", "“Play it here. Whoever wants to hear it can come.”", "“Let it be heard only once, at the Heart.”"] },
      molino: { say: ["They take it to the summit. Aspa loads it into a windmill. The next day, the whole Glade hears the Crater: blows, sparks, foremen shouting.",
                      "At the Lake, the Tides folk pound their boats without knowing why. In the Meadow, the bakers knead with blows. They wear themselves out.",
                      "Now we're the Choir. We did the same thing. Proudly, on top of it. I don't know if it's worse or better."] },
      aqui: { say: ["They hold a night in the Crater square. The workers play the anvils, each to their own rhythm, with no song. People come from other villages to listen. It doesn't stick to them. They carry it away in their memory, not stuck in their heads.",
                    "Whoever wants to, comes. Whoever doesn't, doesn't. That's how music was before the windmills, Hornaza says. It costs more. It's worth more."] },
      corazon: { say: ["They take the anvils to the Heart in carts. One afternoon they play them before the statues, all at once, just once.",
                       "The Root, below, stirs. The heel's note changes for a moment, as if it were answering. Then it goes back to the usual one.",
                       "We played for the Root. Not for people. And the Root answered. The Choir can't buy that."] },
    } },
  });

  /* ---------- Deep Forest: the birds, the moss, the hedge Council, the drinking roots, the leaves that bring words, the Long Silence, the woodcutter and the echoing oak ---------- */
  add("forest", {
    "e7-calandria": { who: { calandria: "Calandria, the bird girl" }, nodes: {
      a: { say: ["Behind the hedges, in a Forest clearing, a twelve-year-old girl has wicker cages hanging from the branches. Inside are birds, still and mute.",
                 "Calandria. I look after the birds that are left. Since the hedges, they don't sing. The wind doesn't get in and they don't know what to sing. They used to learn from the wind, my grandmother says.",
                 "Outside the hedges, the birds sing the Choir's songs. I've heard them. A blackbird was singing “the Houses that shine.” It's horrible. I'd rather mine stayed mute."],
           opts: ["Take the cages to the gap in the hedge", "Teach the birds the lullaby", "“Let them go outside. Let them sing what they want.”"] },
      hueco: { say: ["You hang the cages in front of the gap that opened in the hedge. A little wind comes in, a scrap of song, the noise of leaves.",
                     "On the third day, a bird sings. It isn't the Choir's song. It's a scrap of it, mixed with its own whistle. Something new.",
                     "It chose. It took a little from outside and mixed it with its own. That's singing, isn't it? The rest is repeating."] },
      nana: { say: ["You sit with Calandria in front of the cages and the two of you sing the lullaby to the birds. Once. Ten times. A hundred. Two days.",
                    "A gray bird repeats it. Badly, in bits, but it repeats it. Then another. Within a week, Calandria's clearing sings the lullaby.",
                    "Now the Forest sings the lullaby. Nobody bought it. They learned it from us. My grandmother's going to cry."] },
      soltar: { say: ["Calandria opens the cages on the other side of the hedge. The birds fly off. After a while, from the trees outside, comes the song of the week, whistled.",
                      "They're free. And they sing the Choir's stuff. Free for that."] },
    } },

    "e7-musgobosque": { who: { ligustro: "Ligustro, of the Moss Council" }, nodes: {
      a: { say: ["At the Forest entrance, Ligustro hands out moss for the ears to everyone who comes in. It's mandatory. A new Council sign says so.",
                 "If someone comes in with a song stuck in their head, they sing it inside, and the song stays in the Forest. It's happened. A girl came in singing and within a week half the Forest was singing the same thing.",
                 "Moss in your ears when you come in, until it wears off. That's how the Forest is protected. That's how it was protected in the Long Silence."],
           opts: ["“In the Long Silence the moss was for not hearing. Acebo took it out to listen.”", "Go in without moss", "Put in the moss and go in"] },
      acebo: { say: ["Acebo. My great-grandmother. Yes. She took it out and said the Root spoke more softly if someone listened to it.",
                     "But she didn't have Choir songs on the wind. She had the Root. What we have now is something else. I think. I don't know."] },
      sin: { say: ["You go in without moss. Ligustro protests, but doesn't stop you. Inside, the song of the week slips out of you, softly, as you walk.",
                   "A Forest boy hears it. He repeats it. Ligustro runs after him with a handful of moss.",
                   "See? One. That's what happens. Who cures him now? There's no cure. You wait for the Choir to sell another one."] },
      con: { say: ["You put in the moss. The Forest becomes a green, cottony silence. You walk for an hour. Little by little, the song leaves your head.",
                   "When you take it out, in the heart of the Forest, for the first time you hear something that isn't a song: the water, a branch, your own breathing.",
                   "That. That's what we wanted to keep. Not the silence: what's underneath."] },
    } },

    "e7-concejo": { who: { ligustro: "Ligustro, of the Moss Council", zorzal: "Zorzal, of the Moss Council" }, nodes: {
      a: { say: ["In the Moss Council hall they're debating the height of the hedges. Ligustro wants them taller. A young councilor with a thin beard wants to lower them.",
                 "Zorzal, of the Council. The hedges are making us deaf. We don't sell to the Meadow. We don't buy in the Crater. The children don't know what goes on outside. The Forest is ending up alone.",
                 "Alone and whole. Outside, heads are bought with songs. I'd rather a Forest alone than a Forest bought."],
           opts: ["“Give the hedges gates, and let each person choose.”", "Back Ligustro", "Back Zorzal"] },
      puertas: { say: ["You propose wooden gates in the hedges, every hundred paces. Open by day, closed by night. Whoever wants to, goes out. Whoever comes back, goes through the moss.",
                       "Gates. You can leave and come back. It seems too little to me. It seems right to me.",
                       "Gates. Everything will come in through them. Slowly, but everything. I'll vote for it anyway. Better slowly than all at once."] },
      ligustro: { say: ["The Council votes with Ligustro. The hedges grow another meter. Zorzal leaves the hall without a goodbye.",
                        "A week later, Zorzal and five young families move to the other side of the hedges. That night, from outside, they can be heard singing the Choir's song."] },
      zorzal: { say: ["The Council votes with Zorzal. They lower the hedges to the height of a person. The wind passes over the top. So do the songs.",
                      "That's it. They'll sing our heads full. The children first.",
                      "Yes. And they'll know what goes on outside. And they'll have to choose. Like everyone."] },
    } },

    "e7-raices": { who: { ligustro: "Ligustro, of the Moss Council" }, nodes: {
      a: { say: ["At the foot of the hedges, the earth is dry and black. The old trees nearby have yellow leaves. Ligustro digs with his hands.",
                 "The hedge roots. They go deep. Very deep. They reach the roots of the Root. They drink its sap. That's why they grow so fast. That's why the trees beside them are dying.",
                 "A strange smell rises from the turned earth. Sweet. Like the black sap of the old stories."],
           opts: ["Cut the deepest hedge roots", "“Pull up the hedges on this side.”", "“If the hedges protect, the cost is worth it.”"] },
      cortar: { say: ["You spend a week cutting roots with short axes, on your knees in the black earth. The hedges dry out a little. They don't fall.",
                      "Within a month the old trees beside them put out new leaves. Small, green.",
                      "The hedges stay. Lower, thinner. But they don't suck from the Root anymore. I didn't know protecting cost that much."] },
      arrancar: { say: ["They pull up the hedges on that side of the Forest. An open strip is left. The wind comes in there, with its songs. The old trees breathe.",
                        "One side open. For the Forest to live, you have to let in what you don't want. No Council book says that."] },
      dejar: { say: ["The cost. Yes. A few trees.",
                     "The hedges keep growing. A year later, there's a new clearing in the Forest, where there were oaks. The hedges surround it."] },
    } },

    "e7-hojas": { who: { zorzal: "Zorzal, of the Moss Council" }, nodes: {
      a: { say: ["Over the hedges, the wind brings leaves that aren't from the Forest. They have words handwritten on them: scraps of songs, names, “come to the Meadow,” “the Choir belongs to everyone.”",
                 "Zorzal, of the Council. The Choir throws them from the windmills. If the songs can't get in, the words do. The children collect them. They read them out loud. And when they read them, they stick all the same.",
                 "Ligustro wants to burn them all. I think we should read them. Know what they say."],
           opts: ["Read them out loud with the children, and discuss each one", "Burn them", "Write an answer on the back of each leaf and give them back to the wind"] },
      leer: { say: ["You sit down with the Forest children and Zorzal. You read a leaf. They argue about whether it's true. One says the wind belongs to the Choir. A boy asks who sold the wind to the Choir.",
                    "Nobody knows. They read another. And another. By the end of the afternoon, the children have questions, not songs.",
                    "That's how you read. With questions. Stuck words come unstuck when someone asks them something."] },
      quemar: { say: ["They gather the leaves in a pile and burn them. The smoke rises over the hedges. It smells of ink.",
                      "They're gone. Tomorrow others will fall. Ligustro will burn them every morning. Some day he'll get tired."] },
      responder: { say: ["On the back of each leaf, the children write what they think. “Who sold you the wind?” “Here the birds sing.” “We don't want your song.” They throw them to the wind from the tallest tree.",
                         "A week later, on the summit, Aspa finds leaves written on both sides caught in the sails. She reads them. She keeps them in a drawer.",
                         "Now the wind carries two things. Theirs and ours. It's the first time we've answered the Choir."] },
    } },

    "e7-silencio": { who: { ligustro: "Ligustro, of the Moss Council" }, nodes: {
      a: { say: ["It's the Long Silence. The whole Forest stays silent for an entire day. With the hedges, the silence is total. Not the wind. Not a bird. Ligustro sits against the oldest oak, eyes closed.",
                 "My great-grandmother heard the Root on this day. She said it speaks more softly if someone listens. I never heard it. With the hedges, even less. Nothing gets in. Or out.",
                 "Maybe the Root speaks through the wind. And the wind doesn't get through. Maybe I covered it up with my own hedges."],
           opts: ["Take him to the gap in the hedge to listen", "Sit with him against the oak and listen to the earth", "“If it can't be heard, it can't be heard. Rest.”"] },
      hueco: { say: ["You take Ligustro to the gap in the hedge. He sits facing the gap, in silence. The wind passes. It brings a scrap of a Choir song. And, underneath, something else.",
                     "A long note, low, unchanging. The one from the Root's heel, reaching all the way here beneath everything.",
                     "I heard it. Through the gap. The Root speaks with the same wind the Choir sells. To hear it you have to let the rest in. There's no way to choose only the good."] },
      tierra: { say: ["You sit beside him, your back against the oak. You both put your hands on the earth. An hour goes by. Two.",
                      "At last you feel something: a very slow beat, in the earth, under your hands. It isn't sound. It's like Arpegia's open hand on the chest.",
                      "It can't be heard. It's felt. My great-grandmother heard it with her ears. I, with my hands. Something changed in the Root. Or in us."] },
      descanso: { say: ["Rest. Yes. It's the only thing silence knows how to do now.",
                        "Ligustro falls asleep against the oak. When the Long Silence ends, he wakes and has heard nothing. He goes back to the Council to vote for more hedges."] },
    } },

    "e7-hachuela": { who: { hachuela: "Hachuela, woodcutter" }, nodes: {
      a: { say: ["At the edge of the Forest, outside the hedges, a burly woman is cutting down an oak with a double axe. Beside her, a Choir cart waits with its driver asleep.",
                 "Hachuela, woodcutter. The Choir needs wood for new windmills. It pays well. The Forest oaks are the best: old, straight, hard. The Council says no. But these are outside the hedges. They belong to nobody.",
                 "I have four children and the Forest hasn't bought anything from me since it put up the hedges. What am I supposed to live on?"],
           opts: ["“Let the Council pay you to look after the oaks instead of cutting them.”", "“Cut, but plant two for every one.”", "“Sell. It's your wood.”"] },
      concejo: { say: ["You go to the Council with Hachuela. They argue. Ligustro says there's no money. Zorzal says there's money for hedges and not for oaks.",
                       "In the end they pay Hachuela half of what the Choir pays, to look after the oaks outside. She accepts, grudgingly.",
                       "Half. For not cutting. It's hard for me to understand. My children will eat less. The oaks will outlive my children. That I do understand."] },
      plantar: { say: ["Two for one? They take a hundred years to grow.",
                       "She does it anyway. For every oak she cuts, she plants two acorns. Her children help her. She teaches them which to water first.",
                       "My great-great-grandchildren will have oaks. The Choir, windmills. Some day the Choir will end. The oaks won't."] },
      vender: { say: ["My wood. That's what I say.",
                      "She cuts six oaks that week. The Choir cart leaves loaded for the Heights. A month later, there are two new windmills on the summit."] },
    } },

    "e7-robleeco": { who: { zorzal: "Zorzal, of the Moss Council" }, nodes: {
      a: { say: ["In the middle of the Forest stands the hollow oak, the one that repeated voices. Now, even with the hedges, it repeats songs. The Choir's. The week's. Very softly, from the hollow.",
                 "Zorzal, of the Council. We don't know how they reach it. Through the roots, I think. The wind gets into the ground on the other side of the hedges and comes out here, through the oak.",
                 "Ligustro wants to cut it down. He says it's a door that can't be shut."],
           opts: ["“It was saved once. Don't let them cut it down.”", "Put your head in the hollow and listen to what it really repeats", "“Let them cut it down.”", "Sing something of your own into the hollow"] },
      salvado: { say: ["My grandfather told me. That someone from outside spoke to the Council and the oak stayed. That it repeated the words of a family who lived inside it, in the winter.",
                       "Now it repeats the Choir's. But it's still the same tree. What reaches it isn't its fault."] },
      escuchar: { say: ["You put your head in the hollow. It smells of damp wood. The Choir's songs play softly. But underneath, lower, there are other voices: a family, a child asking for bread, a woman singing the lullaby in the cold.",
                        "The oak didn't change its memory. New songs were laid on top, but the old ones are still there, underneath, like layers of bark.",
                        "Both things. The Choir's and what came before. If we cut it down, we lose both."] },
      cortar: { say: ["The Council cuts down the oak. It takes a whole day: it's enormous. When it falls, the hollow splits in two. A sigh comes out, long, of many voices.",
                      "It doesn't repeat anymore. Not the Choir's, not what came before. Ligustro is happy. I can't look at the trunk."] },
      cantar: { say: ["You lean toward the hollow and sing something of your own, whatever comes out. The oak falls silent a moment. Then it repeats it, softly, in your voice.",
                      "The next day, in the Forest, your song can be heard coming from the oak, mixed with the Choir's. Some children learn it from there.",
                      "Now the oak has something of its own too. Yours. It's strange for a tree to sing something nobody sold."] },
    } },
  });

  /* ==================== Delivery 3: the Hollow, the Lake and the Caves ==================== */

  /* ---------- Shady Hollow: second-hand songs, the mocking name, the wells that keep songs, the collector, the wedding, the archive of names and Sigilo's daughter ---------- */
  add("hollow", {
    "e7-mirla": { who: { mirla: "Mirla, seller of used songs" }, nodes: {
      a: { say: ["Among the dry wells, a young shadow has a stall of planks covered in folded papers. She sells old songs, last week's, at half price.",
                 "Mirla. I sell used songs. The ones folk up top don't sing anymore. For us they work just the same: they cover the name. An old song is an old house, but it has a roof.",
                 "The Choir says I can't. That songs are theirs even when nobody wants them anymore. Tomorrow a collector is coming to shut my stall."],
           opts: ["“Let the Choir prove an old song belongs to it.”", "Help her write songs of her own to sell", "“Pay them a share. Then they'll leave you alone.”"] },
      probar: { say: ["The next day the Choir's collector arrives. You ask him for the paper that says the song belongs to the Choir. He looks. He has the one for the new song. Not the old one: nobody wrote it down.",
                      "The shadows watching start singing the old song, all at once. The collector leaves with the stall still open.",
                      "An old song belongs to nobody. Not even the Choir. Now we know. The Choir knows too, and next time it'll keep better records."] },
      propias: { say: ["You spend three nights writing with Mirla. Shadow songs are slow, with no strong words, so as not to draw attention.",
                       "Some of them sell. They don't stick in your head: you have to learn them. The shadows learn them anyway.",
                       "A song you have to learn costs more. It costs time. But once you know it, it's yours. Nobody can come and collect it."] },
      parte: { say: ["A share. Yes. What I earned for bread.",
                     "Mirla pays. The stall stays open. The songs go up in price. The shadows buy fewer, and sing more softly."] },
    } },

    "e7-zarzo": { who: { zarzo: "Zarzo, young shadow" }, nodes: {
      a: { say: ["At the edge of the Hollow, a shadow boy covers his ears with his hands. From the street above, some children sing a short, mocking song. There's a name in the song.",
                 "Zarzo. Not that one. The one they sing is the other one, the true one. My mother owed money to a family from the Houses. They paid the Choir for a song with my name in it. So everyone would know. So I'd be ashamed.",
                 "I can't use it anymore. Not even for my mother to call me. If anyone says it, people laugh, because they remember the song."],
           opts: ["“Keep Zarzo. Put the other one away.”", "Write different words with the same name, words that don't mock", "Go to the Houses and pay off the mother's debt"] },
      nuevo: { say: ["Put it away? My mother gave it to me. It was the only thing she didn't owe anyone.",
                     "He thinks it over for a night. The next day he asks to be called Zarzo, nothing more. He keeps the true name. He doesn't tell it even to his mother.",
                     "Now I have two. One for outside. One for inside. That's how shadows have always lived. I thought I'd be different."] },
      letra: { say: ["With Zarzo you write a song with his true name in it, but about a boy who helps his mother carry water from the well. You sing it in the street above.",
                     "It doesn't stick as much as the other. But some people sing it. When the children start the mocking, someone answers with the other words.",
                     "Now my name has two songs. One laughs. The other doesn't. I can choose which one to hear."] },
      deuda: { say: ["You go to the Houses with the coins. The family accepts the payment. But the song is already on the wind: it can't be taken back.",
                     "We don't owe anymore. The song goes on. Paying doesn't erase what was sung. Thank you anyway. My mother slept tonight."] },
    } },

    "e7-pozos": { who: { murria: "Murria, Gualda's granddaughter" }, nodes: {
      a: { say: ["The shadows of the Hollow sing inside the dry wells. They lean over the rim and sing downward, slowly. Then they leave, relieved.",
                 "Murria. My grandmother was Gualda, the one who greeted everyone by name. Here we keep the songs we can't pay for anymore. We sing them into the well and the well keeps them. When the Choir comes to collect, they're not in our heads anymore.",
                 "The trouble is the wells are filling up. Yesterday, in the middle well, a song rose up on its own. One someone stored a year ago. It came out twisted."],
           opts: ["“Your grandmother came back to the Hollow with her name. What would she do?”", "Empty the wells: sing back everything stored, all at once", "Cover the full wells and open new ones", "“Stop storing. Pay or forget.”"] },
      gualda: { say: ["My grandmother said a kept name rots. That you have to say it even if it hurts. She said hers. They threw her out twice. She came back both times.",
                      "I suppose she'd say the same about songs. That you don't keep them in a well. You sing them, or let them go."] },
      vaciar: { say: ["For a whole night, the shadows stand around the wells and sing what they stored. All at once. From the depths rises the noise of a hundred mingled songs.",
                      "At dawn, the wells are empty and the shadows hoarse. Nobody remembers the songs. But they sang them one last time, their own way.",
                      "They're gone. Better gone sung than rotten. My grandmother would laugh. She never kept anything."] },
      tapar: { say: ["They cover the full wells with stones and open two new ones, deeper, at the edge of the Hollow.",
                     "Deeper, more room. In a few years they'll fill up too. And someone will cover those. Until the Hollow is a single covered well."] },
      olvidar: { say: ["Pay or forget. What the Choir says.",
                       "Some shadows stop storing. The ones who can't pay, forget. An old woman forgets the lullaby she sang to her daughter. She searches the well for it all night. It's gone."] },
    } },

    "e7-mochuelo": { who: { mochuelo: "Mochuelo, Choir collector" }, nodes: {
      a: { say: ["Down the shadows' street walks a short man in a gray cloak, with a leather bag. He knocks on a door. An old shadow comes out. He puts a hand on her forehead. The shadow stares into nothing.",
                 "Mochuelo, collector. Don't look at me like that. It's my job. The Choir lends songs. If they're not paid for, they're collected. With forgetting shade: I take it out of your head. I learned it from an old man at the well, one of the old ones.",
                 "This lady owed three songs. I took all three. The trouble is forgetting shade doesn't choose well. Sometimes it takes something else. A name. A face. It's not my fault."],
           opts: ["“Take only the song. If you can't, take nothing.”", "Pay the old woman's debt", "Take him to the Hollow council", "“It's your job. Carry on.”"] },
      solo: { say: ["And if I can't? The Choir pays me per song collected.",
                    "You go with him all afternoon. At every door, he tries carefully. Twice he stops: he feels he's about to take something more. He doesn't collect.",
                    "Two songs uncollected. I'll cover them out of my own pocket. I don't know why I listen to you. Maybe because the old man at the well said that too: only what's owed."] },
      pagar: { say: ["You pay for the three songs. Mochuelo gives you a receipt. The old woman doesn't remember the songs: the payment came too late. But she isn't staring into nothing anymore.",
                     "Paid. What I already took doesn't come back to her. But I won't be back tomorrow. That's worth something."] },
      consejo: { say: ["You take Mochuelo to the Hollow council. They argue all afternoon. In the end they ban collecting with forgetting inside the Hollow.",
                       "Within a month, the Choir stops lending songs to the shadows. The shadows sing the old ones, the used ones, the ones from the well. More softly.",
                       "I'm out of work here. I'm off to collect in the Meadow. There's no council there to forbid it."] },
      seguir: { say: ["Thank you. Hardly anyone says that.",
                      "He goes on down the street, door by door. By the end of the afternoon the bag is heavy. The shadows on that street don't sing anymore. They don't remember what."] },
    } },

    "e7-boda": { who: { mirla: "Mirla, seller of used songs", zarzo: "Zarzo, young shadow" }, nodes: {
      a: { say: ["A wedding is being set up in the shadows' street. There are well flowers, Tides bread and a long table. The couple are two young shadows: a song seller and a skinny young man.",
                 "Mirla. I'm marrying him. Here, ever since the Court scattered, a wedding is done by saying your true name in front of everyone. It's the law of the Hollow. That way nobody marries under a false name.",
                 "Zarzo. And my true name is sung in a mocking song. If I say it in front of everyone, they'll laugh. At my own wedding."],
           opts: ["Marry them with the hand gesture, without saying the name out loud", "“Whisper it to each other. Let the rest witness that you said it.”", "“It's the law. Say it out loud.”"] },
      manos: { say: ["You teach them Arpegia's gesture: the open hand on the chest, closed, toward the other. “I promise.” They do it face to face. Then each says their name with their hands.",
                     "Nobody understands it. Everyone sees it. The Hollow council argues for a while over whether it counts. An old woman says yes: she saw how their hands were shaking.",
                     "We got married without anyone hearing our names. And everyone knows we said them. It's the most our own thing I have."] },
      oido: { say: ["Mirla leans in and whispers something in Zarzo's ear. He answers the same way. The whole street goes silent, watching.",
                    "She knows it. I know hers. Nobody else. That's not the law. But the council said it'll do, this once.",
                    "Within a year, three more couples marry by whisper. The law of the Hollow isn't changed. It just stops being used."] },
      ley: { say: ["Zarzo says his name out loud. Someone at the back hums the mocking song. There's laughter. Mirla squeezes his hand.",
                   "He said it. In front of everyone. Some laughed. Tomorrow they'll forget the wedding and remember the song."] },
    } },

    "e7-carrizo": { who: { carrizo: "Carrizo, Legajo's grandson" }, nodes: {
      a: { say: ["In the archive of the Veil, among shelves of tied papers, a man in smoked spectacles looks after the true names the scattered Court left behind. On the desk, a letter with the Choir's seal.",
                 "Carrizo, Legajo's grandson. The Choir wants to buy the archive. All the names. They say it's to write a song with everyone in it, “so nobody is left out.” They're offering what the whole Hollow is worth.",
                 "My grandfather kept these names so nobody would use them. If I sell them, every name will be in the head of the whole Glade. If I don't, the Hollow stays poor."],
           opts: ["“Your grandfather copied the archive so it wouldn't depend on one place.”", "Give each shadow back their own page", "Burn the archive", "“Sell it. It's a lot of money.”"] },
      copia: { say: ["Yes. There's a copy in the Caves, in the Hondura. My grandfather trusted nobody, not even himself.",
                     "So selling this one isn't enough. The Choir will want both. That buys me time. I don't know what for."] },
      devolver: { say: ["You spend a week handing out pages along the shadows' street. Each one gets her own: a paper with her true name, written by someone who died years ago.",
                        "Some burn it. Others keep it against their chest. One pins it to her door.",
                        "The archive is empty. The Choir has nothing to buy. Each name now belongs to whoever carries it. My grandfather didn't dare. Neither did I, until today."] },
      quemar: { say: ["That night they burn the archive in the yard. The pages rise up burning. The smoke smells of old ink.",
                      "Nobody can sell them. Nobody can read them. Not even the shadows who wanted to know their grandmother's name. That burned too."] },
      vender: { say: ["Carrizo sells. Within a month, the Choir lets loose on the wind a long, slow song with hundreds of names. It sticks. The Meadow children sing it without knowing whose names they are.",
                      "The Hollow has money. The shadows have their names in everyone's mouth. I don't know which of the two will last longer."] },
    } },

    "e7-sigilohija": { who: { sigilo: "Sigilo, landless shadow" }, nodes: {
      a: { say: ["In the street given to the shadows, at night, Sigilo sits in the doorway of her house. She isn't singing. It's the first time you've seen her silent.",
                 "Sigilo. Do you remember me? Since we got the street, I sing less. There are nights I don't sing at all. It frightens me. Without a song, someone could say my name.",
                 "My daughter wants to know my name. The true one. She's eight. If I tell her, she'll say it in the street without meaning to. Children don't keep anything."],
           opts: ["“Tell her. And teach her to keep it.”", "“Wait until she's older.”", "“Tell her in a song. That way it sounds like a song, not a name.”"] },
      decir: { say: ["Sigilo calls her daughter. She whispers the name in her ear. The girl repeats it softly, three times, and laughs.",
                     "The next day, the girl doesn't say it in the street. She draws it in the dust with a finger and rubs it out with her foot.",
                     "She kept it. On her own. At eight. It took us centuries to learn that. Her, one night."] },
      esperar: { say: ["Older. Yes. When she knows how to keep quiet.",
                       "The girl doesn't ask again. But that night, in bed, she makes up a name for her mother and sings it to her. Sigilo hears it from the doorway. She doesn't correct her."] },
      cantando: { say: ["Sigilo sings her daughter a slow song, one of the street's. In the middle, between two notes, she puts her name.",
                        "The girl learns the song. She doesn't know there's a name inside. She'll sing it all her life.",
                        "She has it. She doesn't know she has it. Some day someone will ask her what that part means. That day she'll understand."] },
    } },
  });

  /* ---------- Mirror Lake: the Choir's diver, the Meadow folk on the shore, the lighthouse horn, the drowning children, the song of the drowned and the dreamers who ask for water ---------- */
  add("lake", {
    "e7-lamprea": { who: { lamprea: "Lamprea, Choir diver" }, nodes: {
      a: { say: ["In a Choir boat, in the middle of the Lake, a skinny man ties a stone to his waist. In his hand he holds a large conch shell, sealed with wax.",
                 "Lamprea, diver. The Choir pays me to go down with the conch open. What the Tides sing down there goes into the conch. I seal it, come up, and the Choir loads it onto the wind.",
                 "I've been down twice. The Tides didn't see me. This is the third. They say what's down there is the lullaby, the true one. It's worth ten windmills."],
           opts: ["Warn the Tides", "Go down with him and make him really listen", "“Let him dive. It's his job.”"] },
      avisar: { say: ["You row to the Tides' shore and tell them about the conch. Albufera says nothing. That afternoon, when Lamprea dives, the Tides are already down there, waiting.",
                      "They surround him in the green water. They don't touch him. They sing to him with closed mouths, very close. He comes up without opening the conch.",
                      "I couldn't. They were there, watching me, singing to me. You don't rob someone who's singing to your face. The Choir will dock my day's pay."] },
      bajar: { say: ["You tie on a stone and dive with Lamprea. Below, the Tides are singing. He opens the conch. You touch his arm and point to the closed mouths: listen, don't keep.",
                     "He stays in the water a long while, without moving. When you surface, he throws the conch into the lake, open.",
                     "It was the lullaby. The one my grandmother sang to me. She was from the Tides. I didn't know it came from here. I won't sell it to anyone."] },
      dejar: { say: ["Lamprea dives. He comes up with the conch full. Within a week, the wind carries all over the Glade a slow lullaby, with bubbles, that nobody can stop humming.",
                     "The Tides hear it on the shore. They look at each other. That night they don't go down to sing."] },
    } },

    "e7-totora": { who: { totora: "Totora, of the Meadow" }, nodes: {
      a: { say: ["On the Lake's south shore, where nobody used to live, there are new reed huts. Meadow families moved here, far from the squares. A woman kneads bread with hands covered in mud.",
                 "Totora, of the Meadow. Back there you couldn't sleep: every night, the latest song. Here the wind reaches less, because of the water. And they say nothing reaches below. We want to learn to sing below, like the Tides.",
                 "The Tides don't want that. They say what's below is theirs. That if we learn, the Choir will buy from us what they won't sell."],
           opts: ["Talk to Albufera so she'll teach them", "“Learn to live with little song, without diving.”", "“Go back to the Meadow. The Lake belongs to the Tides.”"] },
      ensenar: { say: ["You talk to Albufera. She takes a while to answer. In the end she agrees, on one condition: what is sung below never comes up. Not sold, not told.",
                       "Totora dives for the first time and comes up crying. She doesn't say what she heard.",
                       "I promised not to tell. I'm keeping it. My children will grow up with something that can't be told. In the Meadow that didn't exist."] },
      poca: { say: ["Totora and the Meadow families build their life on the shore with little song: whistles, the sound of water, bread being slapped. At first they can hardly sleep for all the silence.",
                    "After a month, I remembered a song my grandmother used to sing. On its own, with no wind. It was there, under all the others. It needed silence to come up."] },
      volver: { say: ["Go back. To sleep with the Houses' song in my ear.",
                      "Two families go back to the Meadow. Totora stays. A year later, the reed huts are empty, except one."] },
    } },

    "e7-faro": { who: { caracola: "Caracola, Calima's granddaughter" }, nodes: {
      a: { say: ["In the Lake lighthouse, a broad-shouldered woman cleans the glass of the lamp. Below, on the pier, Choir folk unload a huge metal horn, shaped like a flower.",
                 "Caracola, Calima's granddaughter. The Choir wants to put the horn up top, instead of the light. They say that in fog boats steer better by a song than by a lamp. That light doesn't stick. A song does.",
                 "They're a little bit right. In fog the light can't be seen at twenty meters. A song can be heard at a hundred. But the song they'll play is the Houses' one. The boats will come home singing someone else's words."],
           opts: ["“Your grandmother lit the lighthouse when nobody wanted it.”", "“Let the horn play a single note, with no words.”", "“Light and song, both. The song, a Tides one.”", "“Let them put up the horn.”"] },
      prendido: { say: ["She lit it. Yes. On a night when the Lake didn't want light. A boat came back. A man's, who afterwards shouted at her for saving him.",
                        "My grandmother said a lighthouse doesn't choose whom it guides. That's why it isn't sold."] },
      nota: { say: ["Caracola accepts the horn, on one condition: a single note, long, low, with no words. The Choir protests: a note doesn't sell.",
                    "The first foggy night, the note sounds over the Lake. The boats come home following it. Nobody hums it afterwards. It has nothing to stick.",
                    "A note that guides and doesn't stick. That's a lighthouse. The Choir took the big horn away and left us a small one. It's enough."] },
      mareas: { say: ["The light stays up top. The horn, below, plays an old Tides fishing song, one of those that isn't sold.",
                      "The boats come home singing ours. Some from outside too. It sticks to them. Now we're the ones doing the sticking. I don't know if that's better."] },
      bocina: { say: ["They put the horn up top. The lamp ends up in a corner. In the fog, the Houses' song sounds over the whole Lake.",
                      "The boats come home. The fishermen step ashore humming. In the lighthouse, Caracola cleans the glass of an unlit lamp."] },
    } },

    "e7-ahogo": { who: { albufera: "Albufera, of the Tides" }, nodes: {
      a: { say: ["On the Tides' shore people stand around a soaked boy, laid out on the stones. Albufera presses on his chest. The boy coughs up water and opens his eyes.",
                 "He stayed down singing. Too long. The children want to sing below like the grown-ups, because up top everything sticks to them. Yesterday another. Today this one.",
                 "The elders want to forbid the children from diving. If they don't dive, up top their heads fill with Choir songs. If they dive, they drown. What do we leave them?"],
           opts: ["“Let them always dive with a grown-up, tied by a rope.”", "“Teach them to sing up top with their mouths closed, like below.”", "“Forbid it until they're older.”"] },
      soga: { say: ["They form pairs: a grown-up and a child, tied at the waist with net rope. When the child stays down too long, the grown-up pulls.",
                    "Nobody drowns anymore. The children sing below with someone watching over them. That's how we all learned, really. We'd forgotten."] },
      boca: { say: ["Albufera gathers the children on the shore. She teaches them to sing with closed mouths, like below, but up top. It sounds strange: the hum of a hive.",
                    "After a while they discover something: singing like that, the wind's songs don't get in. Their own hum covers them.",
                    "Below, above. It doesn't matter. What matters is the closed mouth. They learned it today. I found out at forty."] },
      prohibir: { say: ["The Tides council forbids the children from diving. Within a month, the Tides children sing the Choir's songs on the shore, like the Meadow children.",
                        "Nobody drowns. Now they drown in something else. More slowly."] },
    } },

    "e7-ahogados": { who: { albufera: "Albufera, of the Tides" }, nodes: {
      a: { say: ["At the foot of the pier there are stones with names carved on them: the Lake's drowned, from many generations. This morning, a Choir singer sits there, copying the names onto a sheet of paper.",
                 "They want to make a song of the drowned. A sad song, to make people cry. They say sad songs stick better than happy ones. And that grief sells.",
                 "Half those names are my family's. Nobody asked us."],
           opts: ["“The stones were carved so the names wouldn't be lost, not to sing them.”", "Ask the singer to hear the stories before writing", "Throw the singer off the pier", "“If people cry, they learn something.”"] },
      piedras: { say: ["My grandmother carved three. She said a name on a stone doesn't move. That in a song it moves with the wind and reaches any mouth.",
                       "Now that you say it, I don't want my dead in just any mouth."] },
      historias: { say: ["You take the singer to the Tides' houses. He listens all afternoon: who each one was, what they fished, what made them laugh.",
                         "In the end he tears up the paper. He writes a song about one single person, a fisherman who laughed at storms. He asks the family's permission before selling it. They say no. He doesn't sell it.",
                         "A Choir singer who asks permission. I'd never seen that. We fed him. He left empty-handed."] },
      echar: { say: ["The Tides throw the singer off the pier. He leaves with the paper in his pocket.",
                     "Within a month, the wind brings a sad song with Lake names in it. Some are wrong. People cry anyway.",
                     "We didn't let him copy. He copied from memory. Badly. Now my dead have different names in everyone's mouth."] },
      dejar: { say: ["The singer finishes copying. The song comes out within the week. It's beautiful. The whole Glade cries to it.",
                     "They cry for my dead without knowing who they were. The third time they hear it, they don't cry anymore. They hum it."] },
    } },

    "e7-suenosagua": { who: { albufera: "Albufera, of the Tides", grumo: "Grumo, eldest dreamer" }, nodes: {
      a: { say: ["On the Lake's north shore, where the water touches the cold of the Deep, a group of dreamers waits wrapped in blankets. An old man with frosted hair steps forward.",
                 "Grumo, eldest dreamer. The wind steals our dreams. It carries them up to the windmills and the Choir sells them as songs. We hardly dream anymore. They say under the water the wind doesn't reach.",
                 "We've come to ask the Tides to let us sleep below. One hour. To dream something nobody can take.",
                 "You can't sleep under water. Nobody lasts that long. Not even us."],
           opts: ["“The Tides and the Deep already know each other. They helped each other once.”", "“Let the Tides sing them the lullaby below while they go under for a moment.”", "“Let them sleep on the shore, with one ear in the water.”", "“It can't be done. Let them go back to the Deep.”"] },
      fondo: { say: ["That's true. My grandmother said that once the Deep paid for the Tides, or the Tides for the Deep. I don't remember which.",
                     "Both. That's why we came. An old debt is better than none."] },
      nana: { say: ["The Tides go down first. The dreamers, one by one, go under for a few seconds, with a Tides hand on their back. Below, the lullaby can be heard, with bubbles.",
                    "None of them falls asleep. But when he comes out, Grumo's eyes are wet with something other than water.",
                    "I didn't dream. But I heard something the wind doesn't have. Tonight, in the Deep, I'll dream of it. And nobody will take it from me."] },
      orilla: { say: ["The dreamers lie down on the shore, heads to one side and one ear in the cold water. The Tides sing below, close by.",
                      "That night, some of them dream. The dreams still rise to the wind, but wet, slow. The windmills can't catch them well.",
                      "Wet dreams. The Choir doesn't know how to sell them. They slip through its fingers."] },
      volver: { say: ["To the Deep. Yes. There we sleep without dreaming. It's like not sleeping.",
                      "The dreamers leave across the ice. Albufera watches them go for a long while."] },
    } },
  });

  /* ---------- Echo Caves: the gallery that charges, the tired wall, the old man who scraped, the twisted promise, the Choir buying the echo, Mica's name and the note that doesn't twist ---------- */
  add("caves", {
    "e7-silice": { who: { silice: "Sílice, miner" }, nodes: {
      a: { say: ["At the mouth of the echo gallery, a young woman in a miner's helmet has a line of Meadow children waiting. She charges a coin to go in for ten minutes.",
                 "Sílice, miner. Inside, the echo twists the Choir's songs. They come out new. Strange. The children go in, listen, and come out singing something nobody else has. Cheaper than the Choir.",
                 "The Choir says the twisted ones are theirs too. Cuarcita says the gallery isn't for selling. I say the Hondura has eaten stone for a century and now it has something to sell that isn't stone."],
           opts: ["“Let them in for free, and on the way out have them read the original words on the wall.”", "“Share what you charge with the whole Hondura.”", "“Close the gallery.”"] },
      gratis: { say: ["Sílice lets them in for free, with one rule: on the way out, each one reads on Cuarcita's wall the song as it was before the echo.",
                      "The children come out singing the twisted one, but laughing at what changed. Some sing both.",
                      "I earn nothing now. But now they come to the Hondura to learn something, not to buy. My grandfather dug so others could eat. I dig so others can think. It doesn't pay better."] },
      repartir: { say: ["Sílice keeps charging, but what she earns goes into the Hondura's pot. That week, the miners eat meat.",
                        "The Hondura sells echoes. We eat. The twisted ones stick up top and people fight over verses nobody wrote. The pot doesn't fix that."] },
      cerrar: { say: ["Close it? And who eats?",
                      "She closes it. That night, the Meadow children get in anyway, through a crack. With nobody charging, nobody watching."] },
    } },

    "e7-paredcansada": { who: { pared: "The wall", cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["In the oldest gallery, the repeating wall speaks. For a century it has repeated what it was told. Now it repeats the Choir's songs, all mixed together, day and night. A Hondura woman has her ear pressed to the stone.",
                 "...the Houses that shine... the Quarter's bread... the Houses... I promise... the Houses...",
                 "Cuarcita, of the Hondura. It's tired. My mother said the wall has memory, not will. But this looks like tiredness. It repeats faster. It stumbles. Some nights it screams."],
           opts: ["“The wall rested once before, when someone listened to all of it.”", "Read the wall what's carved on it, so it hears something that isn't a song", "Seal the crack the wind gets in through", "“It's a wall. Let it repeat.”"] },
      aliviada: { say: ["My mother listened to it a whole night, as a girl. She said afterwards the wall spoke more slowly. Like someone who'd told what they had to tell.",
                        "Now one night isn't enough. Too much gets in."] },
      leer: { say: ["You spend the night with Cuarcita reading the wall its carved lines: the winter firewood, the names, the pact. Slowly, softly.",
                    "At dawn, the wall repeats one of the lines. “The Root rests if someone looks after it.” Once. Then it falls silent for a long while.",
                    "It repeated something true. Something nobody bought. And then it rested. My mother was right: memory. And memory fills up with rubbish too."] },
      tapar: { say: ["They seal the crack the wind gets in through with mud. The wall goes silent all at once, in the middle of a word.",
                     "It doesn't repeat anything now. Not the bad, not the good. I don't know if we cured it or put it to sleep."] },
      dejar: { say: ["The wall goes on. That night it screams. The next day, a new crack appears in the stone. Cuarcita touches it with her hand and says nothing."] },
    } },

    "e7-raspaviejo": { who: { raspa: "Raspa, the old man with the knife", cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["At night, in the echo gallery, there's the sound of stone on stone. With the lamp you find a stooped old man, with a worn iron knife, scraping the twisted lines off a wall.",
                 "Raspa. Years ago I erased what I was paid to. Now I erase for free. I erase the twisted ones, the ones the echo makes up. Nobody said those. They don't deserve stone.",
                 "Cuarcita doesn't want me to. She says they should be left next to the true ones. I say a lie in stone becomes true over the years. I know. I erased truths. Now I erase lies. It's the same knife."],
           opts: ["“Someone once taught you to carve instead of erase.”", "Let him erase", "Take him to Cuarcita to argue it out"] },
      graba: { say: ["Carve. Yes. Mica taught me, when she was a girl. She made me carve my own name next to what I'd erased.",
                     "Raspa puts the knife away. He takes out a nail. Next to each twisted line, he carves a small mark: a spiral, like an echo.",
                     "Now you can tell which is which. I didn't erase anything. It's the first night of my life I haven't erased anything. My hands hurt just the same."] },
      borrar: { say: ["Raspa erases all night. At dawn, the wall has smooth hollows where the twisted lines were.",
                      "A week later, up top, people are still fighting over the twisted verses. There's no stone left to show them where they came from.",
                      "I erased the lie. And the proof of the lie. The same thing always happens to me."] },
      discutir: { say: ["You take Raspa to Cuarcita's house. They argue until late: he wants to erase, she wants to leave them. In the end they agree on something neither of them wanted.",
                        "The twisted ones go to another gallery. Raspa copies them there, all together, and erases the ones here. A gallery of lies, with a sign. My mother would laugh.",
                        "A whole gallery of lies. Mine. At my age. At least this time I know what I'm copying."] },
    } },

    "e7-yeso": { who: { yeso: "Yeso, miner" }, nodes: {
      a: { say: ["In the Hondura square, a young miner's face is red. Behind him, some children sing a short song. A woman, across the square, cries with her face in her hands.",
                 "Yeso, miner. I promised to marry her. In the echo gallery, out loud, so the stone would keep it. It's the custom here.",
                 "The echo twisted it. It came out “I promise you nothing.” The children heard it. Now they sing it everywhere. She thinks the echo said what I was thinking."],
           opts: ["“Promise her again, face to face, without the gallery.”", "Take them to Cuarcita's wall to carve the promise as it was said", "Teach them to promise with their hands"] },
      frente: { say: ["Yeso crosses the square. He stands in front of her. He says it again, softly, with no echo. The children keep singing behind him.",
                      "She looks at him a long while. She takes his hand. She doesn't say yes. She doesn't say no.",
                      "She'll answer me in a month, she says. She wants to see whether the one who promises is the one in the square or the one in the echo."] },
      pared: { say: ["With Cuarcita you carve the promise on the wall, letter by letter, as Yeso said it. Next to it, small, what came out of the echo.",
                     "She comes down to read it. She reads it twice. Then she reads the twisted one and laughs for the first time in a week.",
                     "The stone says what I said. The echo says what I didn't. And she chose to read the stone."] },
      manos: { say: ["You show them Arpegia's gesture. Yeso makes it facing her: the open hand on the chest, closed, toward her. No sound. No echo.",
                     "She answers with the same gesture.",
                     "There was nothing to twist. No stone repeated it. No child can sing it. She saw it. That's enough."] },
    } },

    "e7-ecocompra": { who: { bordon: "Bordón, the Choir's treasurer", cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["At the entrance to the echo gallery, a man in an embroidered waistcoat measures the stone mouth with a tape. Behind him, two laborers with wheelbarrows.",
                 "Bordón, the Choir's treasurer. The Choir wants to buy the gallery. The echo twists songs, and the twisted ones stick better. If we twist them ourselves, here, before letting them loose, they stick twice as well. We pay well.",
                 "Cuarcita, of the Hondura. The gallery isn't ours. It belongs to the stone. The Hondura doesn't sell stone that speaks."],
           opts: ["“Rent it out one hour a week, and carve everything the Choir twists.”", "Break the gallery's roof so the echo is lost", "“Sell it. The Hondura needs money.”"] },
      alquilar: { say: ["Carve what we twist? Then everyone will know how we do it.",
                        "He accepts anyway: he needs the echo. One hour a week, the Choir twists songs in the gallery. Cuarcita carves each one: how it went in and how it came out.",
                        "Now the wall shows how a song that sticks is made. Anyone can come down and see. The Choir sells the trick and we give it away."] },
      romper: { say: ["That night, with picks, they break part of the gallery's roof. Light gets in for the first time in centuries. The echo is lost upward.",
                      "It doesn't twist anymore. It doesn't repeat. The gallery is just a gallery. My mother would cry. I don't know what to do with my hands."] },
      vender: { say: ["The Hondura sells. The Choir puts an iron door on the gallery. Within a week, the songs coming out of there stick like never before.",
                      "We eat. Up top they fight over verses we twisted. Now the Hondura really does sell memory. Other people's."] },
    } },

    "e7-mica": { who: { cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["Cuarcita takes you to a small gallery, the deepest in the Hondura. On the wall there are thousands of lines in small, cramped handwriting. At the end, an empty space.",
                 "Cuarcita. My mother carved all this. What others erased. Names, debts, pacts. She never carved her own. She said whoever carves doesn't get carved. She died last winter.",
                 "I want to carve her name here. But she didn't want that. And if I carve it, the echo in the next gallery will repeat it twisted. “Mica, the one who lied.” “Mica, the one who erased.” It's happened to others."],
           opts: ["“Your mother didn't forget when they told her to forget.”", "“Carve it, and next to it what she did.”", "“Respect what she wanted.”", "“Make a mark only you will understand.”"] },
      firme: { say: ["No. As a girl they told her to forget what she heard in the wall. She didn't forget. It cost her half her friends.",
                     "She was always like that. She did what nobody wanted. Not even herself."] },
      grabar: { say: ["Cuarcita carves her mother's name in the empty space. Below it, a line: “She carved what others erased.” It takes her all night.",
                      "A week later, the echo in the next gallery repeats the name. Twisted. But the people who come down to see the wall read the line below.",
                      "The echo does its thing. The stone, its own. My mother is in both. Let each person choose which to believe."] },
      respetar: { say: ["Whoever carves doesn't get carved. Yes.",
                        "She leaves the space empty. As she leaves, she rests her hand for a moment on the smooth stone, where the name would go.",
                        "The day I die, someone will find two empty spaces. They'll think we were forgotten. That's what she wanted. I don't know if it's what I want."] },
      marca: { say: ["Cuarcita rests her hand on the stone and, with her fingernail, scratches a fine line, barely visible. Just one. Nobody who doesn't know will see it.",
                     "The echo doesn't repeat what can't be heard. And this can't be heard. It's my mother. And I know it."] },
    } },

    "e7-notaeco": { who: { cuarcita: "Cuarcita, of the Hondura" }, nodes: {
      a: { say: ["In the echo gallery, a Hondura woman tries something: she sings the long note of the Root's heel, the one that comes from the Heart and nobody buys. The echo repeats it.",
                 "Cuarcita. Listen. It repeats it the same. Untwisted. It's the only thing the echo doesn't change. I tried everything: lullabies, names, Choir songs. Everything comes out twisted. Not this.",
                 "If the Choir finds out, they'll want to know why. And they'll want to sell it. A note that doesn't twist is worth more than any song."],
           opts: ["Carve on the wall that the echo doesn't twist the heel's note", "Keep the secret", "Sing it every day into the echo, so it mixes with the twisted ones"] },
      grabar: { say: ["Cuarcita carves on the wall: “The echo doesn't twist the heel's note.” Below it, the date. Below that, her name.",
                      "Within a week, people from all over the Glade come down to try. They sing the note. The echo gives it back whole. Some cry without knowing why.",
                      "The Choir came down too. It tried. It can't sell it: it's one single note, and it belongs to everyone. It left angry. It's the best thing that's happened in the Hondura this year."] },
      secreto: { say: ["Cuarcita doesn't carve it. She asks you not to tell. That night she goes down to the gallery and sings the note until late.",
                       "It's mine. One thing the echo respects. I won't spend it on anyone."] },
      cantar: { say: ["Every day, at dawn, Cuarcita goes down and sings the heel's note into the echo. The note mixes with the twisted ones, again and again.",
                      "Within a month, the twisted songs come out a little less twisted. As if the note were straightening them, little by little.",
                      "The note doesn't twist, and it straightens the others. I don't know why. My mother would say the Root doesn't lie. I don't know if the Root knows how to lie."] },
    } },
  });
})(window.EVEVENTS_EN);
